INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-1-1','cet4-2025-06-1',100,0,'Psychologists have long been interested in how we construct our identities and the sorts of strategies that we use to present ourselves in society.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-1-2','cet4-2025-06-1',100,1,'New findings suggest that the kinds of complex and strategic self-presentation behaviour we see in adults appear at a much younger age than previously known.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-2-1','cet4-2025-06-1',101,0,'Research shows that a child’s awareness of social standing comes from adults.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-2-2','cet4-2025-06-1',101,1,'Like grown-ups, kids want to be accepted by those they admire.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-2-3','cet4-2025-06-1',101,2,'Interactive experiences may provide opportunities for children to learn about what constitutes a desirable reputation and the kinds of strategies that are effective for building a good reputation in their social environment.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-3-1','cet4-2025-06-1',102,0,'Five-year-olds aren’t just aware of their reputations, they also behave strategically to alter their outward image.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-3-2','cet4-2025-06-1',102,1,'They will vary their behaviour in order to appear moral or socially good in the eyes of key observers.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-3-3','cet4-2025-06-1',102,2,'While we know that adults use a large variety of attributes to manage and create impressions, we don’t yet know whether children understand and use the fact that different attributes are valuable at different times to different audiences.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-3-4','cet4-2025-06-1',102,3,'It’s important for us to further consider where in this process children succeed in controlling their reputation and where they struggle.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-4-1','cet4-2025-06-1',103,0,'A question to think about is, “What happens even earlier than age five?”','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-4-2','cet4-2025-06-1',103,1,'Children don’t just show up to the first day of kindergarten and have the idea of reputation pop suddenly into existence.','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-2-sentence-4-3','cet4-2025-06-1',103,2,'The logical question to ask is, “What happens even earlier?”','cet4-2025-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-1-section-3','cet4-2025-06-1',2,'matching','长篇阅读（36–45）· Getting young minds into design','In this section, you are going to read a passage with ten statements attached to it. Each statement contains information given in one of the paragraphs. Identify the paragraph from which the information is derived. You may choose a paragraph more than once. Each paragraph is marked with a letter. Answer the questions by marking the corresponding letter on Answer Sheet 2.','["[A] Recently, a leading design federation in the UK warned that the UK could face a creative skills shortage, after the latest figures revealed a drop of almost 10 percent in students studying Design and Technology. These figures showed that the number of pupils that sat exams in Design and Technology fell 10 percent from 204,788 to 185,279 last year.","[B] Chief executive John Kampfner of the Creative Industries Federation thinks that this drop in figures has worrying implications for the skills pipeline in Britain’s hugely successful arts and creative industries. He said, “We already have skills shortages in many jobs such as animation (动画制作) and special effects.” He added: “Engineering, which requires a similar mix of creative and technical skills, also has recruitment problems.”","[C] Many other designers and architects have expressed concern over the future supply of home-grown talent for UK firms, and industry bodies have pointed out that there has been a lack of roots-level support. However, if these designers had visited the Design Museum shop in London earlier this year their fears may have been eased. With £10 to spend, they could have bought a fascinating children’s toy called “Dazzle Racer”. An automotive cylinder (圆柱体), it included a wind-up, elastic (有弹性的)-band-powered mechanism, minimal parts, all 100 percent recycled, and lots of stickers. It was good fun, simple, eye-catching and very original.","[D] Well, you’d expect the Design Museum to commission and make some interesting items, but this one was different. Designed by a group of six Year 9 and Year 10 boys from Finchley Catholic High School, the toy was the winning entry in the museum’s 2015 Design Ventura competition, which brings the business of design to life for students aged 13 to 16 by challenging them to develop a new creative, sustainable and commercially feasible product for the Design Museum shop and attracts hundreds of entries nationwide.","[E] “We did Design Ventura in my previous school,” says Liam Hourican, Finchley Catholic High School’s design technology curriculum leader, “Then when I changed schools four years ago, I introduced it here because it helps to develop so many skills.”","[F] The theme for last year’s competition was “Move”, and Hourican began with three groups working in lunch breaks and after school before selecting the group with the most innovative idea. Each participating school may submit just one proposal. “It’s the taking part and doing the work which is important,” he says. “And I never dreamt we’d win.”","[G] Catherine Ritman Smith, head of learning at the Design Museum, is expecting around 10,000 participants aged 13 to 16 to take part this year and says that the project—funded by Deutsche Bank as part of its youth engagement programme Born To Be—is the biggest event in the museum’s calendar. “We started Design Ventura with around 800 young people in 2010 and it has grown steadily since,” she says. “Teachers like it because the skills are all transferable and it helps to validate the value of design as a subject,” she explains, telling me that nearly 600 schools have taken part so far.","[H] So how does the competition work? A single-word theme is announced in the summer. This year it is “Change”. Schools work with groups to produce imaginative design ideas for a product in simple materials that could sell for £10 in the Design Museum shop. Participating schools then register by November and eventually submit their design idea. Along the way there is training and support for teachers and tutoring for students from designers. An additional bonus is when the winners see their design on sale in the spring of the following year.","[I] Hourican and his pupils have happy memories of spending a whole day at the museum, having been selected as one of 10 shortlisted schools to present their idea to a panel of judges, including designer Jasper Conran. Then they worked with the Kin Design Studio in Shoreditch, met designers at their school and attended a lunch with Deutsche Bank employees. The students helped to make decisions and there were plenty of discussions—they changed the product’s name, for example.","[J] “One of the really useful things about this competition,” says Hourican, “is that there’s a commercial element because the product is going on sale for real and the boys had to learn about budgeting and marketing, as well as designing their game.” Profits go to charity. “The winning team chooses where it wants the profits to go,” says Ritman Smith. “The Finchley Catholic High School product raised about £1,000 for Great Ormond Street Hospital.” Winning entries in past years have included a make-your-own cloth kit called Dove Bunting and a threefold, wallet-sized travel game with goals at each end, called Badoiiing.","[K] It costs the schools nothing to participate in Design Ventura; the professional designers provide their services for free. Among them are architect Asif Khan, a Design Museum trustee who has worked as designer-in-residence at the museum, helping emerging architects. He has recently been commissioned to design the new Museum of London building in Smithfield.","[L] Another is television presenter and interior designer Naomi Cleaver, who is one of the competition’s judges. “I’m very keen to encourage young people,” she says, observing that design brings together other subjects such as literature, art, history, geography and science. “Now that design education is limited in the curriculum, I’m all in favour of competitions such as Design Ventura, which helps to bring the standard curriculum to life,” says Cleaver. “And the judging day is terrific fun. Some of these students are very imaginative. One group presented their idea in the form of a puppet show and we see some marvelous demonstration models. I’m always impressed by the levels of confidence and the support the students get from their teachers.”","[M] Ritman Smith adds: “Design technology has become a tricky subject to make a case for, and we’ve heard of departments closing in some schools. We find that if pupils take part in Design Ventura in Year Nine it can be the trigger which leads them to opt for it at General Certificate of Secondary Education, so we are helping to keep alive something which is crucial to industry and entrepreneurship.”"]','["Recently, a leading design federation in the UK warned that the UK could face a creative skills shortage, after the latest figures revealed a drop of almost 10 percent in students studying Design and Technology. These figures showed that the number of pupils that sat exams in Design and Technology fell 10 percent from 204,788 to 185,279 last year.","Chief executive John Kampfner of the Creative Industries Federation thinks that this drop in figures has worrying implications for the skills pipeline in Britain’s hugely successful arts and creative industries. He said, “We already have skills shortages in many jobs such as animation (动画制作) and special effects.” He added: “Engineering, which requires a similar mix of creative and technical skills, also has recruitment problems.”","Many other designers and architects have expressed concern over the future supply of home-grown talent for UK firms, and industry bodies have pointed out that there has been a lack of roots-level support. However, if these designers had visited the Design Museum shop in London earlier this year their fears may have been eased. With £10 to spend, they could have bought a fascinating children’s toy called “Dazzle Racer”. An automotive cylinder (圆柱体), it included a wind-up, elastic (有弹性的)-band-powered mechanism, minimal parts, all 100 percent recycled, and lots of stickers. It was good fun, simple, eye-catching and very original.","Well, you’d expect the Design Museum to commission and make some interesting items, but this one was different. Designed by a group of six Year 9 and Year 10 boys from Finchley Catholic High School, the toy was the winning entry in the museum’s 2015 Design Ventura competition, which brings the business of design to life for students aged 13 to 16 by challenging them to develop a new creative, sustainable and commercially feasible product for the Design Museum shop and attracts hundreds of entries nationwide.","“We did Design Ventura in my previous school,” says Liam Hourican, Finchley Catholic High School’s design technology curriculum leader, “Then when I changed schools four years ago, I introduced it here because it helps to develop so many skills.”","The theme for last year’s competition was “Move”, and Hourican began with three groups working in lunch breaks and after school before selecting the group with the most innovative idea. Each participating school may submit just one proposal. “It’s the taking part and doing the work which is important,” he says. “And I never dreamt we’d win.”","Catherine Ritman Smith, head of learning at the Design Museum, is expecting around 10,000 participants aged 13 to 16 to take part this year and says that the project—funded by Deutsche Bank as part of its youth engagement programme Born To Be—is the biggest event in the museum’s calendar. “We started Design Ventura with around 800 young people in 2010 and it has grown steadily since,” she says. “Teachers like it because the skills are all transferable and it helps to validate the value of design as a subject,” she explains, telling me that nearly 600 schools have taken part so far.","So how does the competition work? A single-word theme is announced in the summer. This year it is “Change”. Schools work with groups to produce imaginative design ideas for a product in simple materials that could sell for £10 in the Design Museum shop. Participating schools then register by November and eventually submit their design idea. Along the way there is training and support for teachers and tutoring for students from designers. An additional bonus is when the winners see their design on sale in the spring of the following year.","Hourican and his pupils have happy memories of spending a whole day at the museum, having been selected as one of 10 shortlisted schools to present their idea to a panel of judges, including designer Jasper Conran. Then they worked with the Kin Design Studio in Shoreditch, met designers at their school and attended a lunch with Deutsche Bank employees. The students helped to make decisions and there were plenty of discussions—they changed the product’s name, for example.","“One of the really useful things about this competition,” says Hourican, “is that there’s a commercial element because the product is going on sale for real and the boys had to learn about budgeting and marketing, as well as designing their game.” Profits go to charity. “The winning team chooses where it wants the profits to go,” says Ritman Smith. “The Finchley Catholic High School product raised about £1,000 for Great Ormond Street Hospital.” Winning entries in past years have included a make-your-own cloth kit called Dove Bunting and a threefold, wallet-sized travel game with goals at each end, called Badoiiing.","It costs the schools nothing to participate in Design Ventura; the professional designers provide their services for free. Among them are architect Asif Khan, a Design Museum trustee who has worked as designer-in-residence at the museum, helping emerging architects. He has recently been commissioned to design the new Museum of London building in Smithfield.","Another is television presenter and interior designer Naomi Cleaver, who is one of the competition’s judges. “I’m very keen to encourage young people,” she says, observing that design brings together other subjects such as literature, art, history, geography and science. “Now that design education is limited in the curriculum, I’m all in favour of competitions such as Design Ventura, which helps to bring the standard curriculum to life,” says Cleaver. “And the judging day is terrific fun. Some of these students are very imaginative. One group presented their idea in the form of a puppet show and we see some marvelous demonstration models. I’m always impressed by the levels of confidence and the support the students get from their teachers.”","Ritman Smith adds: “Design technology has become a tricky subject to make a case for, and we’ve heard of departments closing in some schools. We find that if pupils take part in Design Ventura in Year Nine it can be the trigger which leads them to opt for it at General Certificate of Secondary Education, so we are helping to keep alive something which is crucial to industry and entrepreneurship.”"]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-36','cet4-2025-06-1-section-3',0,'choice','36. During the course of preparing for Design Ventura, teachers receive training and support while students get tutoring from designers.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','H','参考答案 H，依据原文整理。H 段跨页说明准备比赛时教师获得培训和支持，学生得到设计师指导。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-37','cet4-2025-06-1-section-3',1,'choice','37. A visit to the Design Museum shop in London can reduce the designers’ fears about the future supply of talents educated in Britain.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','C','参考答案 C，依据原文整理。C 段说设计师参观伦敦设计博物馆商店后，对本土人才供给的担忧可能会缓解。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-38','cet4-2025-06-1-section-3',2,'choice','38. One of Design Ventura’s judges says the competition adds vigour to the standard curriculum in schools.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','L','参考答案 L，依据原文整理。评委 Naomi Cleaver 在 L 段说比赛 helps to bring the standard curriculum to life。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-39','cet4-2025-06-1-section-3',3,'choice','39. Enrollment in Design and Technology decreased by nearly ten percent last year in the UK.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','A','参考答案 A，依据原文整理。A 段给出报考 Design and Technology 的人数下降近 10% 的数据。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-40','cet4-2025-06-1-section-3',4,'choice','40. Participation of ninth graders in Design Ventura can motivate them to choose design technology as their subject.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','M','参考答案 M，依据原文整理。M 段说九年级参与比赛可促使学生在后续考试中选择设计技术学科。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-41','cet4-2025-06-1-section-3',5,'choice','41. Design Ventura is welcomed by teachers because it helps to prove the worth of design as a school subject.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','G','参考答案 G，依据原文整理。G 段说教师喜欢比赛，因为技能可以迁移，并能证明设计学科的价值。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-42','cet4-2025-06-1-section-3',6,'choice','42. The schools don’t have to pay anything to take part in the Design Ventura competition.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','K','参考答案 K，依据原文整理。K 段明确指出学校参加比赛无需费用，专业设计师免费提供服务。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-43','cet4-2025-06-1-section-3',7,'choice','43. Participants in Design Ventura are challenged to create sustainable and marketable products.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','D','参考答案 D，依据原文整理。D 段介绍比赛要求学生开发具有创意、可持续且商业上可行的产品。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-44','cet4-2025-06-1-section-3',8,'choice','44. Students benefit from Design Ventura because they can learn about budgeting and marketing in addition to game design.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','J','参考答案 J，依据原文整理。J 段说学生除设计游戏外，还需要学习预算和营销。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-3-q-45','cet4-2025-06-1-section-3',9,'choice','45. According to an officer of the Creative Industries Federation, there is difficulty now in recruiting engineers in the UK.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','B','参考答案 B，依据原文整理。B 段中行业联合会负责人指出工程行业也存在招聘困难。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
