INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-2-section-2','cet4-2025-06-2',1,'cloze','选词填空（26–35）','In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list of choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding letter for each item on Answer Sheet 2 with a single line through the centre. You may not use any of the words in the bank more than once.','["Sir Alfred Hitchcock was an English movie director and producer. Famously [26] ______ to as ‘The Master of Suspense,’ Hitchcock is one of the most influential filmmakers in the history of [27] ______ . He was an extraordinary director who entertained his audience with [28] ______ and gripping suspense movies.","His fascination with crime began at an early age when he was [29] ______ by his father who made him spend a few minutes inside a prison for his misconduct. Hence, his movies are [30] ______ of the guilt and innocence of the wrongdoer and the victim. He had a gift for creating stories that consisted of deceit, robbery, murder, corruption, and other criminal [31] ______ with incredible plot twists in the storyline. The principal characters in his movies were often ordinary people [32] ______ in unwanted and unavoidable situations.","He was [33] ______ productive and his amazing body of work is considered fascinating by the critics. Most of his movies have [34] ______ the test of time and are considered to be masterpieces. He is also remembered by other filmmakers, for he continues to inspire them to be passionate about their work. He is also [35] ______ by people around the world for his entertaining and exciting stories."]','["Sir Alfred Hitchcock was an English movie director and producer. Famously referred to as ‘The Master of Suspense,’ Hitchcock is one of the most influential filmmakers in the history of cinema. He was an extraordinary director who entertained his audience with engaging and gripping suspense movies.","His fascination with crime began at an early age when he was punished by his father who made him spend a few minutes inside a prison for his misconduct. Hence, his movies are symbolic of the guilt and innocence of the wrongdoer and the victim. He had a gift for creating stories that consisted of deceit, robbery, murder, corruption, and other criminal offences with incredible plot twists in the storyline. The principal characters in his movies were often ordinary people caught in unwanted and unavoidable situations.","He was highly productive and his amazing body of work is considered fascinating by the critics. Most of his movies have stood the test of time and are considered to be masterpieces. He is also remembered by other filmmakers, for he continues to inspire them to be passionate about their work. He is also worshipped by people around the world for his entertaining and exciting stories."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-2-q-26','cet4-2025-06-2-section-2',0,'choice','26. 第 26 空','[{"key":"A","text":"caught"},{"key":"B","text":"cinema"},{"key":"C","text":"engaging"},{"key":"D","text":"graphically"},{"key":"E","text":"highly"},{"key":"F","text":"incentive"},{"key":"G","text":"instincts"},{"key":"H","text":"offences"},{"key":"I","text":"punished"},{"key":"J","text":"referred"},{"key":"K","text":"stood"},{"key":"L","text":"symbolic"},{"key":"M","text":"tuned"},{"key":"N","text":"visually"},{"key":"O","text":"worshipped"}]','J','参考答案 J，依据原文整理。be referred to as 表示“被称为”，这里介绍希区柯克的称号 The Master of Suspense。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-2-q-27','cet4-2025-06-2-section-2',1,'choice','27. 第 27 空','[{"key":"A","text":"caught"},{"key":"B","text":"cinema"},{"key":"C","text":"engaging"},{"key":"D","text":"graphically"},{"key":"E","text":"highly"},{"key":"F","text":"incentive"},{"key":"G","text":"instincts"},{"key":"H","text":"offences"},{"key":"I","text":"punished"},{"key":"J","text":"referred"},{"key":"K","text":"stood"},{"key":"L","text":"symbolic"},{"key":"M","text":"tuned"},{"key":"N","text":"visually"},{"key":"O","text":"worshipped"}]','B','参考答案 B，依据原文整理。in the history of cinema 指电影史，与前文 movie director 和 filmmakers 呼应。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-2-q-28','cet4-2025-06-2-section-2',2,'choice','28. 第 28 空','[{"key":"A","text":"caught"},{"key":"B","text":"cinema"},{"key":"C","text":"engaging"},{"key":"D","text":"graphically"},{"key":"E","text":"highly"},{"key":"F","text":"incentive"},{"key":"G","text":"instincts"},{"key":"H","text":"offences"},{"key":"I","text":"punished"},{"key":"J","text":"referred"},{"key":"K","text":"stood"},{"key":"L","text":"symbolic"},{"key":"M","text":"tuned"},{"key":"N","text":"visually"},{"key":"O","text":"worshipped"}]','C','参考答案 C，依据原文整理。engaging 与 gripping 并列修饰 suspense movies，表示引人入胜的悬疑电影。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
