INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-3-section-2','cet4-2025-06-3',1,'cloze','选词填空（26–35）','In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list of choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding letter for each item on Answer Sheet 2 with a single line through the centre. You may not use any of the words in the bank more than once.','["The human brain has the ability to constantly form new networks and connections between brain cells. This means the brain has an almost magical ability to change. This characteristic is [26] ______ apparent in a new study, focusing on people who underwent a hemispherectomy, a surgical procedure in which half of the brain is removed to treat illness. The findings showed that, despite missing half of this critical [27] ______ , participants could function well. This was because the [28] ______ half of their brain strengthened. In fact, researchers found that connections—and thus communication—between parts of different brain networks are actually stronger in people who had hemispherectomies than in people with intact brains. This [29] ______ that the brain is able to compensate for loss of certain brain structure.","There are many other cases in the medical [30] ______ that document the brain’s amazing ability to [31] ______ . For example, a young boy had a significant portion of his brain removed for medical reasons, which included the part of the brain [32] ______ for sight. But a few years after his surgery, scientists found that he could [33] ______ see. They determined that this was because other parts of his brain took over the missing part’s [34] ______ tasks. Another study involved people who could smell, despite missing the region in the brain that processes information about smells. Though they are not sure how these individuals [35] ______ the ability to smell, scientists believe it is possible that another part of the brain took on that task."]','["The human brain has the ability to constantly form new networks and connections between brain cells. This means the brain has an almost magical ability to change. This characteristic is particularly apparent in a new study, focusing on people who underwent a hemispherectomy, a surgical procedure in which half of the brain is removed to treat illness. The findings showed that, despite missing half of this critical organ, participants could function well. This was because the remaining half of their brain strengthened. In fact, researchers found that connections—and thus communication—between parts of different brain networks are actually stronger in people who had hemispherectomies than in people with intact brains. This indicates that the brain is able to compensate for loss of certain brain structure.","There are many other cases in the medical literature that document the brain’s amazing ability to adapt. For example, a young boy had a significant portion of his brain removed for medical reasons, which included the part of the brain responsible for sight. But a few years after his surgery, scientists found that he could still see. They determined that this was because other parts of his brain took over the missing part’s visual tasks. Another study involved people who could smell, despite missing the region in the brain that processes information about smells. Though they are not sure how these individuals retained the ability to smell, scientists believe it is possible that another part of the brain took on that task."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
