INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-2-q-31','cet4-2025-06-3-section-2',5,'choice','31. 第 31 空','[{"key":"A","text":"adapt"},{"key":"B","text":"hardly"},{"key":"C","text":"indicates"},{"key":"D","text":"insist"},{"key":"E","text":"literature"},{"key":"F","text":"organ"},{"key":"G","text":"particularly"},{"key":"H","text":"remaining"},{"key":"I","text":"responsible"},{"key":"J","text":"retained"},{"key":"K","text":"still"},{"key":"L","text":"strategy"},{"key":"M","text":"transformed"},{"key":"N","text":"underlines"},{"key":"O","text":"visual"}]','A','参考答案 A，依据原文整理。ability to adapt 表示适应能力，下文举例说明其他脑区能够接替失去的功能。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
