INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-2-sentence-1-6','cet4-2025-06-3',100,5,'In fact, researchers found that connections—and thus communication—between parts of different brain networks are actually stronger in people who had hemispherectomies than in people with intact brains.','cet4-2025-06-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
