INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-2-sentence-2-1','cet4-2025-06-3',101,0,'There are many other cases in the medical literature that document the brain’s amazing ability to adapt.','cet4-2025-06-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-2-sentence-2-2','cet4-2025-06-3',101,1,'For example, a young boy had a significant portion of his brain removed for medical reasons, which included the part of the brain responsible for sight.','cet4-2025-06-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-2-sentence-2-3','cet4-2025-06-3',101,2,'But a few years after his surgery, scientists found that he could still see.','cet4-2025-06-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-2-sentence-2-4','cet4-2025-06-3',101,3,'They determined that this was because other parts of his brain took over the missing part’s visual tasks.','cet4-2025-06-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-2-sentence-2-5','cet4-2025-06-3',101,4,'Another study involved people who could smell, despite missing the region in the brain that processes information about smells.','cet4-2025-06-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-2-sentence-2-6','cet4-2025-06-3',101,5,'Though they are not sure how these individuals retained the ability to smell, scientists believe it is possible that another part of the brain took on that task.','cet4-2025-06-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-3-section-3','cet4-2025-06-3',2,'matching','长篇阅读（36–45）· “Phantom” Traffic Jams Are Real—And Scientists Know How to Stop Them','In this section, you are going to read a passage with ten statements attached to it. Each statement contains information given in one of the paragraphs. Identify the paragraph from which the information is derived. You may choose a paragraph more than once. Each paragraph is marked with a letter. Answer the questions by marking the corresponding letter on Answer Sheet 2.','["[A] Traffic jams are a common problem of most big cities, either in developed or in developing countries, but one kind of traffic jams in particular can be especially frustrating. These are generally known as “phantom” traffic jams, in which dense traffic crawls to a halt for no apparent reason at all.","[B] “When caught in such a traffic jam, it is common for drivers to assume that there must be an accident, or construction or something,” said Massachusetts Institute of Technology (MIT) computer science professor Berthold Horn. “And then you drive and drive and drive… and there isn’t anything there.”","[C] The exact cause of these phantom traffic jams has long remained a mystery. But now, new research has found the cause and researchers may have come up with a solution for this frustrating traffic pattern: maintaining equal spacing between cars on the road, rather than driving so closely behind another vehicle that a collision (碰撞) is likely if that vehicle brakes suddenly.","[D] Horn said phantom traffic jams are an emergent property of the flow of vehicles down a highway. A phantom jam begins when a car in dense traffic slows down even slightly, which causes the car behind that vehicle to slow even more—and the slowing action spreads backward through the lane of traffic like a wave, getting worse the farther it spreads. Eventually, the cars far behind are forced to stop completely or risk hitting the slower vehicles ahead—and so the traffic grinds to a halt over nothing, Horn said.","[E] Horn has been working on the problem of phantom traffic jams for years, and he has come up with a solution: By splitting the difference between the cars in front and the cars behind, the spacing of cars in a stream of traffic can act as a damper (抑制) on phantom traffic jams. That is, it can prevent the slow-down effect from being amplified (增强) by the cars that follow behind, he said. In essence, each driver would constantly make adjustments to keep their car roughly halfway between the car in front and the car behind.","[F] Horn calls this method of vehicle spacing bilateral (双边的) control, and he said it could be achieved with relatively simple modifications to the adaptive cruise control that many new cars already have. Adaptive cruise control is a driver assistance technology that sets a maximum speed for vehicles and automatically slows the speed of the car when traffic is sensed in front of the vehicle. The technology is also known as autonomous cruise control. Such modifications, Horn said, could help fight phantom jams within a few years, maybe decades before an alternative solution, such as networked self-driving cars, becomes a reality on the roads.","[G] Traffic jams are caused by a number of factors, such as roads that are poorly designed or over-capacity, localized factors like city traffic-lighting patterns, and events like accidents and construction. But phantom traffic jams can make all those problems worse, Horn said. And the researchers in the new study have calculated that solving phantom jams could save at least some of the estimated $121 billion per year that traffic jams are estimated to cost the U.S. economy, Horn told Live Science.","[H] New research by Horn and MIT postdoctoral associate Liang Wang, published in the journal IEEE Transactions on Intelligent Transportation Systems, shows how bilateral control can fight the problem. The researchers made computer models of real-world traffic conditions, showing how a typical U.S. freeway could benefit from cars using bilateral control. That would be in place when human drivers fail to slow down, thus avoiding tailgating (紧跟) the car in front, Horn said. “Under reasonable conditions today, you might get 1,800 cars per lane per hour throughput (the volume of traffic passing through),” he added. “But with bilateral control, you could almost double that.”","[I] The main alternative to increasing traffic throughput per lane has been to build more lanes and more highways, and putting in new roads is very expensive, he said. “If we can increase the throughput on major highways, even if it’s only by 50 percent, that would be a big deal,” Horn said.","[J] With the help of engineering students at high schools in Maine, Horn and Wang have also built a robot simulation ( 模拟) that shows how bilateral control can suppress phantom traffic jams. Increasing the spacing of vehicles dampens the effect of slowdowns by cars in front of a given car, so that the slowing is not worsened until it becomes a phantom jam, the researchers said.","[K] A video from the project shows a train of autonomous robots running along a track without bilateral control; they eventually back up in phantom jams. But when the robots are switched over to bilateral control (by flashing the lights in the room), each autonomous robot tries to keep itself halfway between the robot in front and the one behind; the phantom jams disappear as a result, Horn said.","[L] Since starting his research on phantom traffic jams, Horn has learned that schools of fish and flocks of birds and bats use similar spacing strategies to avoid hitting each other while swimming or flying in densely packed groups. In particular, studies of millions of bats emerging at dusk from caves in Southeast Asia showed that each bat used a form of bilateral control to reduce the likelihood of collisions with other bats in the densely packed swarm (一大群), Horn said.","[M] Unlike bats, birds and fish, however, humans have difficulty judging distances behind them. To address that weakness, Horn is now working with the car company Toyota to enable a form of bilateral control via modifications to existing adaptive cruise control systems, which use forward-facing sensors to judge the distance to the vehicle ahead. The bilateral control approach would include adding rear-facing sensors to determine the distance to the vehicle following a car.","[N] But until those systems become standard, human drivers can help reduce phantom traffic jams simply by not following the car in front so closely. As Horn argues, “There’s absolutely no advantage of tailgating the car in front of you.”"]','["Traffic jams are a common problem of most big cities, either in developed or in developing countries, but one kind of traffic jams in particular can be especially frustrating. These are generally known as “phantom” traffic jams, in which dense traffic crawls to a halt for no apparent reason at all.","“When caught in such a traffic jam, it is common for drivers to assume that there must be an accident, or construction or something,” said Massachusetts Institute of Technology (MIT) computer science professor Berthold Horn. “And then you drive and drive and drive… and there isn’t anything there.”","The exact cause of these phantom traffic jams has long remained a mystery. But now, new research has found the cause and researchers may have come up with a solution for this frustrating traffic pattern: maintaining equal spacing between cars on the road, rather than driving so closely behind another vehicle that a collision (碰撞) is likely if that vehicle brakes suddenly.","Horn said phantom traffic jams are an emergent property of the flow of vehicles down a highway. A phantom jam begins when a car in dense traffic slows down even slightly, which causes the car behind that vehicle to slow even more—and the slowing action spreads backward through the lane of traffic like a wave, getting worse the farther it spreads. Eventually, the cars far behind are forced to stop completely or risk hitting the slower vehicles ahead—and so the traffic grinds to a halt over nothing, Horn said.","Horn has been working on the problem of phantom traffic jams for years, and he has come up with a solution: By splitting the difference between the cars in front and the cars behind, the spacing of cars in a stream of traffic can act as a damper (抑制) on phantom traffic jams. That is, it can prevent the slow-down effect from being amplified (增强) by the cars that follow behind, he said. In essence, each driver would constantly make adjustments to keep their car roughly halfway between the car in front and the car behind.","Horn calls this method of vehicle spacing bilateral (双边的) control, and he said it could be achieved with relatively simple modifications to the adaptive cruise control that many new cars already have. Adaptive cruise control is a driver assistance technology that sets a maximum speed for vehicles and automatically slows the speed of the car when traffic is sensed in front of the vehicle. The technology is also known as autonomous cruise control. Such modifications, Horn said, could help fight phantom jams within a few years, maybe decades before an alternative solution, such as networked self-driving cars, becomes a reality on the roads.","Traffic jams are caused by a number of factors, such as roads that are poorly designed or over-capacity, localized factors like city traffic-lighting patterns, and events like accidents and construction. But phantom traffic jams can make all those problems worse, Horn said. And the researchers in the new study have calculated that solving phantom jams could save at least some of the estimated $121 billion per year that traffic jams are estimated to cost the U.S. economy, Horn told Live Science.","New research by Horn and MIT postdoctoral associate Liang Wang, published in the journal IEEE Transactions on Intelligent Transportation Systems, shows how bilateral control can fight the problem. The researchers made computer models of real-world traffic conditions, showing how a typical U.S. freeway could benefit from cars using bilateral control. That would be in place when human drivers fail to slow down, thus avoiding tailgating (紧跟) the car in front, Horn said. “Under reasonable conditions today, you might get 1,800 cars per lane per hour throughput (the volume of traffic passing through),” he added. “But with bilateral control, you could almost double that.”","The main alternative to increasing traffic throughput per lane has been to build more lanes and more highways, and putting in new roads is very expensive, he said. “If we can increase the throughput on major highways, even if it’s only by 50 percent, that would be a big deal,” Horn said.","With the help of engineering students at high schools in Maine, Horn and Wang have also built a robot simulation ( 模拟) that shows how bilateral control can suppress phantom traffic jams. Increasing the spacing of vehicles dampens the effect of slowdowns by cars in front of a given car, so that the slowing is not worsened until it becomes a phantom jam, the researchers said.","A video from the project shows a train of autonomous robots running along a track without bilateral control; they eventually back up in phantom jams. But when the robots are switched over to bilateral control (by flashing the lights in the room), each autonomous robot tries to keep itself halfway between the robot in front and the one behind; the phantom jams disappear as a result, Horn said.","Since starting his research on phantom traffic jams, Horn has learned that schools of fish and flocks of birds and bats use similar spacing strategies to avoid hitting each other while swimming or flying in densely packed groups. In particular, studies of millions of bats emerging at dusk from caves in Southeast Asia showed that each bat used a form of bilateral control to reduce the likelihood of collisions with other bats in the densely packed swarm (一大群), Horn said.","Unlike bats, birds and fish, however, humans have difficulty judging distances behind them. To address that weakness, Horn is now working with the car company Toyota to enable a form of bilateral control via modifications to existing adaptive cruise control systems, which use forward-facing sensors to judge the distance to the vehicle ahead. The bilateral control approach would include adding rear-facing sensors to determine the distance to the vehicle following a car.","But until those systems become standard, human drivers can help reduce phantom traffic jams simply by not following the car in front so closely. As Horn argues, “There’s absolutely no advantage of tailgating the car in front of you.”"]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-36','cet4-2025-06-3-section-3',0,'choice','36. The age-long mystery has now been resolved as to how phantom traffic jams are caused.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','C','参考答案 C，依据原文整理。C 段说长期未解的幽灵堵车原因已被新研究找到，并提出等距行驶的解决办法。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-37','cet4-2025-06-3-section-3',1,'choice','37. It is possible to nearly double the hourly throughput per lane by adopting bilateral control.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','H','参考答案 H，依据原文整理。H 段用每车道每小时约 1,800 辆的现有通行量说明双边控制几乎可以使其翻倍。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-38','cet4-2025-06-3-section-3',2,'choice','38. According to Horn, drivers making constant adjustments for equal spacing between cars in a flow of traffic can help reduce phantom traffic jams.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','E','参考答案 E，依据原文整理。E 段要求驾驶者不断调整，让车辆大致处于前后两车的中间位置，从而抑制减速效应。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-39','cet4-2025-06-3-section-3',3,'choice','39. Before systems for bilateral control are installed, drivers should not follow the car in front too closely so as to reduce phantom traffic jams.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','N','参考答案 N，依据原文整理。N 段说在相关系统普及前，驾驶者不要紧跟前车，也能帮助减少幽灵堵车。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-40','cet4-2025-06-3-section-3',4,'choice','40. Horn said with some simple modifications to the existing equipment in new vehicles, their spacing bilateral control could be accomplished.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','F','参考答案 F，依据原文整理。F 段指出对许多新车已有的自适应巡航控制进行简单修改即可实现双边控制。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-41','cet4-2025-06-3-section-3',5,'choice','41. Drivers caught up in phantom traffic jams are likely to think an accident has happened or some construction is going on.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','B','参考答案 B，依据原文整理。B 段说遭遇幽灵堵车时，驾驶者常以为前方发生事故或正在施工。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-42','cet4-2025-06-3-section-3',6,'choice','42. Two sets of sensors would be used to help drivers determine the distances between cars.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','M','参考答案 M，依据原文整理。M 段同时介绍现有的前向传感器和需要增加的后向传感器，用来判断前后车距。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-43','cet4-2025-06-3-section-3',7,'choice','43. Solving the problem of phantom jams could save America billions of dollars every year.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','G','参考答案 G，依据原文整理。G 段指出缓解幽灵堵车可以减少美国每年估计 1,210 亿美元的堵车经济损失。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-44','cet4-2025-06-3-section-3',8,'choice','44. In a phantom traffic jam, the cars in the same lane slow down one after another, creating a wave-like effect.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','D','参考答案 D，依据原文整理。D 段描述减速向车流后方像波浪一样传播，并不断加重，最终迫使后车停下。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-3-q-45','cet4-2025-06-3-section-3',9,'choice','45. Horn has found that certain creatures use strategies similar to bilateral control to avoid hitting each other while moving in dense crowds.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"}]','L','参考答案 L，依据原文整理。L 段介绍鱼群、鸟群和蝙蝠群采用类似的间距策略，避免密集移动时相撞。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-1-1','cet4-2025-06-3',200,0,'Traffic jams are a common problem of most big cities, either in developed or in developing countries, but one kind of traffic jams in particular can be especially frustrating.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-1-2','cet4-2025-06-3',200,1,'These are generally known as “phantom” traffic jams, in which dense traffic crawls to a halt for no apparent reason at all.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-2-1','cet4-2025-06-3',201,0,'“When caught in such a traffic jam, it is common for drivers to assume that there must be an accident, or construction or something,” said Massachusetts Institute of Technology (MIT) computer science professor Berthold Horn.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-2-2','cet4-2025-06-3',201,1,'“And then you drive and drive and drive… and there isn’t anything there.”','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-3-1','cet4-2025-06-3',202,0,'The exact cause of these phantom traffic jams has long remained a mystery.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-3-2','cet4-2025-06-3',202,1,'But now, new research has found the cause and researchers may have come up with a solution for this frustrating traffic pattern: maintaining equal spacing between cars on the road, rather than driving so closely behind another vehicle that a collision (碰撞) is likely if that vehicle brakes suddenly.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-4-1','cet4-2025-06-3',203,0,'Horn said phantom traffic jams are an emergent property of the flow of vehicles down a highway.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-4-2','cet4-2025-06-3',203,1,'A phantom jam begins when a car in dense traffic slows down even slightly, which causes the car behind that vehicle to slow even more—and the slowing action spreads backward through the lane of traffic like a wave, getting worse the farther it spreads.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-4-3','cet4-2025-06-3',203,2,'Eventually, the cars far behind are forced to stop completely or risk hitting the slower vehicles ahead—and so the traffic grinds to a halt over nothing, Horn said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-5-1','cet4-2025-06-3',204,0,'Horn has been working on the problem of phantom traffic jams for years, and he has come up with a solution: By splitting the difference between the cars in front and the cars behind, the spacing of cars in a stream of traffic can act as a damper (抑制) on phantom traffic jams.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-5-2','cet4-2025-06-3',204,1,'That is, it can prevent the slow-down effect from being amplified (增强) by the cars that follow behind, he said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-5-3','cet4-2025-06-3',204,2,'In essence, each driver would constantly make adjustments to keep their car roughly halfway between the car in front and the car behind.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-6-1','cet4-2025-06-3',205,0,'Horn calls this method of vehicle spacing bilateral (双边的) control, and he said it could be achieved with relatively simple modifications to the adaptive cruise control that many new cars already have.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-6-2','cet4-2025-06-3',205,1,'Adaptive cruise control is a driver assistance technology that sets a maximum speed for vehicles and automatically slows the speed of the car when traffic is sensed in front of the vehicle.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-6-3','cet4-2025-06-3',205,2,'The technology is also known as autonomous cruise control.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-6-4','cet4-2025-06-3',205,3,'Such modifications, Horn said, could help fight phantom jams within a few years, maybe decades before an alternative solution, such as networked self-driving cars, becomes a reality on the roads.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-7-1','cet4-2025-06-3',206,0,'Traffic jams are caused by a number of factors, such as roads that are poorly designed or over-capacity, localized factors like city traffic-lighting patterns, and events like accidents and construction.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-7-2','cet4-2025-06-3',206,1,'But phantom traffic jams can make all those problems worse, Horn said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-7-3','cet4-2025-06-3',206,2,'And the researchers in the new study have calculated that solving phantom jams could save at least some of the estimated $121 billion per year that traffic jams are estimated to cost the U.S. economy, Horn told Live Science.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-8-1','cet4-2025-06-3',207,0,'New research by Horn and MIT postdoctoral associate Liang Wang, published in the journal IEEE Transactions on Intelligent Transportation Systems, shows how bilateral control can fight the problem.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-8-2','cet4-2025-06-3',207,1,'The researchers made computer models of real-world traffic conditions, showing how a typical U.S. freeway could benefit from cars using bilateral control.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-8-3','cet4-2025-06-3',207,2,'That would be in place when human drivers fail to slow down, thus avoiding tailgating (紧跟) the car in front, Horn said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-8-4','cet4-2025-06-3',207,3,'“Under reasonable conditions today, you might get 1,800 cars per lane per hour throughput (the volume of traffic passing through),” he added.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-8-5','cet4-2025-06-3',207,4,'“But with bilateral control, you could almost double that.”','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-9-1','cet4-2025-06-3',208,0,'The main alternative to increasing traffic throughput per lane has been to build more lanes and more highways, and putting in new roads is very expensive, he said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-9-2','cet4-2025-06-3',208,1,'“If we can increase the throughput on major highways, even if it’s only by 50 percent, that would be a big deal,” Horn said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-10-1','cet4-2025-06-3',209,0,'With the help of engineering students at high schools in Maine, Horn and Wang have also built a robot simulation ( 模拟) that shows how bilateral control can suppress phantom traffic jams.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-10-2','cet4-2025-06-3',209,1,'Increasing the spacing of vehicles dampens the effect of slowdowns by cars in front of a given car, so that the slowing is not worsened until it becomes a phantom jam, the researchers said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-11-1','cet4-2025-06-3',210,0,'A video from the project shows a train of autonomous robots running along a track without bilateral control; they eventually back up in phantom jams.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-11-2','cet4-2025-06-3',210,1,'But when the robots are switched over to bilateral control (by flashing the lights in the room), each autonomous robot tries to keep itself halfway between the robot in front and the one behind; the phantom jams disappear as a result, Horn said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-12-1','cet4-2025-06-3',211,0,'Since starting his research on phantom traffic jams, Horn has learned that schools of fish and flocks of birds and bats use similar spacing strategies to avoid hitting each other while swimming or flying in densely packed groups.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-12-2','cet4-2025-06-3',211,1,'In particular, studies of millions of bats emerging at dusk from caves in Southeast Asia showed that each bat used a form of bilateral control to reduce the likelihood of collisions with other bats in the densely packed swarm (一大群), Horn said.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-13-1','cet4-2025-06-3',212,0,'Unlike bats, birds and fish, however, humans have difficulty judging distances behind them.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-13-2','cet4-2025-06-3',212,1,'To address that weakness, Horn is now working with the car company Toyota to enable a form of bilateral control via modifications to existing adaptive cruise control systems, which use forward-facing sensors to judge the distance to the vehicle ahead.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-13-3','cet4-2025-06-3',212,2,'The bilateral control approach would include adding rear-facing sensors to determine the distance to the vehicle following a car.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-14-1','cet4-2025-06-3',213,0,'But until those systems become standard, human drivers can help reduce phantom traffic jams simply by not following the car in front so closely.','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-3-sentence-14-2','cet4-2025-06-3',213,1,'As Horn argues, “There’s absolutely no advantage of tailgating the car in front of you.”','cet4-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-3-section-4','cet4-2025-06-3',3,'reading','仔细阅读 · Passage One（46–50）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["Our society places a high value on physical beauty. Americans spend an average of over $722 each year on their appearance. One in ten Americans has tried to look like a star.","There’s nothing wrong with trying to look our best, but excessive focus on physical appearance misses the soulful aspects of what it means to be beautiful. Trying to look like the magazine pictures can take us on a long ride away from what beauty is really about.","Many of us spend far too much time, energy, and money trying to polish an image of what we think will bring attention, love, and connection. In the process, we may fail to attend to ourselves in a way that would move us toward deeper intimacy, fulfillment, and meaning.","It may sound trite (老生常谈的), but beauty is only skin deep; it’s not what brings love toward us. Just read about the latest Hollywood starlets whose seeming love turns into resentment and bitter court battles.","Outer beauty can be as much of a curse as a blessing. We may develop a habit of being so focused on maintaining a perfect appearance that we never cultivate the inner qualities necessary to sustain and deepen intimacy and connection. As I describe in my book, The Authentic Heart, it is the courage to be authentic that connects us in a deeper way.","While our initial attraction may be based, in part, on physical chemistry, it is the meeting of our inner worlds that creates the lasting intimacy and spiritual connection for which we long. If we redirect our attention toward cultivating inner qualities, we might find a magnetic attraction that moves us from something superficial to something that connects us to our depths.","The path toward cultivating inner beauty is really simple. But what is simple is not always easy. Not everyone will see us and appreciate us as we take the courageous risk to allow ourselves to be seen as we really are. But if they don’t, it is their loss, not ours. Eventually we’ll find those compatible souls who appreciate us as we are."]','["Our society places a high value on physical beauty. Americans spend an average of over $722 each year on their appearance. One in ten Americans has tried to look like a star.","There’s nothing wrong with trying to look our best, but excessive focus on physical appearance misses the soulful aspects of what it means to be beautiful. Trying to look like the magazine pictures can take us on a long ride away from what beauty is really about.","Many of us spend far too much time, energy, and money trying to polish an image of what we think will bring attention, love, and connection. In the process, we may fail to attend to ourselves in a way that would move us toward deeper intimacy, fulfillment, and meaning.","It may sound trite (老生常谈的), but beauty is only skin deep; it’s not what brings love toward us. Just read about the latest Hollywood starlets whose seeming love turns into resentment and bitter court battles.","Outer beauty can be as much of a curse as a blessing. We may develop a habit of being so focused on maintaining a perfect appearance that we never cultivate the inner qualities necessary to sustain and deepen intimacy and connection. As I describe in my book, The Authentic Heart, it is the courage to be authentic that connects us in a deeper way.","While our initial attraction may be based, in part, on physical chemistry, it is the meeting of our inner worlds that creates the lasting intimacy and spiritual connection for which we long. If we redirect our attention toward cultivating inner qualities, we might find a magnetic attraction that moves us from something superficial to something that connects us to our depths.","The path toward cultivating inner beauty is really simple. But what is simple is not always easy. Not everyone will see us and appreciate us as we take the courageous risk to allow ourselves to be seen as we really are. But if they don’t, it is their loss, not ours. Eventually we’ll find those compatible souls who appreciate us as we are."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-4-q-46','cet4-2025-06-3-section-4',0,'choice','46. What do we learn about American society from the first paragraph?','[{"key":"A","text":"It sees lots of personal income wasted on beauty products."},{"key":"B","text":"It considers one’s physical appearance very important."},{"key":"C","text":"It places a high value on the physical fitness of stars."},{"key":"D","text":"It expects every individual to look their very best."}]','B','参考答案 B，依据原文整理。首段说美国社会高度重视外貌，并列举外貌方面的支出和模仿明星的现象。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-4-q-47','cet4-2025-06-3-section-4',1,'choice','47. What happens when people strive to look better?','[{"key":"A","text":"They have to get prepared for resentment and bitter court battles."},{"key":"B","text":"They are better able to gain attention, love, and personal connection."},{"key":"C","text":"They may neglect to cultivate the inner qualities that matter more."},{"key":"D","text":"They feel much of their precious time, energy and resources is wasted."}]','C','参考答案 C，依据原文整理。文章指出过度追求外表可能让人忽视更有意义的自我关照及维系亲密关系的内在品质。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-4-q-48','cet4-2025-06-3-section-4',2,'choice','48. What does the author say about outer beauty?','[{"key":"A","text":"It may be inherited or cultivated."},{"key":"B","text":"It may lead to bad as well as good habits."},{"key":"C","text":"It may create connection or isolation."},{"key":"D","text":"It may do as much harm as good."}]','D','参考答案 D，依据原文整理。第五段说 Outer beauty can be as much of a curse as a blessing，意为外在美可能既带来好处也带来伤害。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-4-q-49','cet4-2025-06-3-section-4',3,'choice','49. What brings about spiritual connection?','[{"key":"A","text":"Meeting of minds."},{"key":"B","text":"Attraction at first sight."},{"key":"C","text":"Physical chemistry."},{"key":"D","text":"Frequent interaction."}]','A','参考答案 A，依据原文整理。第六段说双方内心世界的交汇创造持久的亲密和精神联系，与 Meeting of minds 对应。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-4-q-50','cet4-2025-06-3-section-4',4,'choice','50. What happens when we take the path toward cultivating inner beauty?','[{"key":"A","text":"We may find a route toward other people’s souls."},{"key":"B","text":"We may be appreciated more by people around us."},{"key":"C","text":"We will meet people who value us for who we are."},{"key":"D","text":"We will be discouraged from revealing our true selves."}]','C','参考答案 C，依据原文整理。末段说培养内在美、展现真实自我，最终能找到欣赏真实自己的契合之人。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
