INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-3-section-5','cet4-2025-06-3',4,'reading','仔细阅读 · Passage Two（51–55）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["Plant-based meats are coming soon to a dinner table near you, but do they deserve a spot on your plate? If you tried a vegetable burger years ago and dismissed it as rubbery and flavorless, it’s a good time to give meatless meat another chance. Newer varieties imitate the look, flavor, and texture of meat. Analysts don’t expect the meat-free movement to slow anytime soon; a 2021 report predicts the market will skyrocket to $74 billion by 2030—a 957 percent surge.","Plant-based meats are no longer just for vegetarians. Companies such as Impossible Foods and Beyond Meat—the current superstars of the alternative protein sector—are pursuing consumers who enjoy meat but want to reduce their meat consumption for animal rights, health, or environmental reasons. So far, it’s a winning strategy: More than nine out of ten consumers who buy Beyond Burger and Impossible Foods products also eat meat.","Many vegetarians don’t actually care for food that resembles meat. When reporter Joan Solsman, a longtime vegetarian, tried a dish from Impossible Foods, she felt so sick that she couldn’t finish it. “Maybe the best sign that Impossible Foods has cracked the code to realistic fake meat is that I couldn’t stand to take another bite,” she wrote.","Meatless meats are generally a healthier choice than beef because they are cholesterol-free, plus they’re a good source of vitamins, minerals, protein, and fiber.","If meatless meat can help you stick to a plant-based diet, that in itself can lead to better health. Not only has red meat been linked to cancer, but studies show that people who ditch meat have lower blood pressure, lower average blood sugar, and lower cholesterol levels.","However, just because it’s plant-based doesn’t mean it’s health food. Most imitation meats are highly processed and contain high amounts of sodium (钠) compared to traditional beef.","These new generations of alternate meat get all the attention, but don’t forget about whole grains and vegetables. Beans are an especially excellent protein substitute. They’re nutritious, inexpensive, and far more sustainable than any of the processed meatless substitutes on the market today."]','["Plant-based meats are coming soon to a dinner table near you, but do they deserve a spot on your plate? If you tried a vegetable burger years ago and dismissed it as rubbery and flavorless, it’s a good time to give meatless meat another chance. Newer varieties imitate the look, flavor, and texture of meat. Analysts don’t expect the meat-free movement to slow anytime soon; a 2021 report predicts the market will skyrocket to $74 billion by 2030—a 957 percent surge.","Plant-based meats are no longer just for vegetarians. Companies such as Impossible Foods and Beyond Meat—the current superstars of the alternative protein sector—are pursuing consumers who enjoy meat but want to reduce their meat consumption for animal rights, health, or environmental reasons. So far, it’s a winning strategy: More than nine out of ten consumers who buy Beyond Burger and Impossible Foods products also eat meat.","Many vegetarians don’t actually care for food that resembles meat. When reporter Joan Solsman, a longtime vegetarian, tried a dish from Impossible Foods, she felt so sick that she couldn’t finish it. “Maybe the best sign that Impossible Foods has cracked the code to realistic fake meat is that I couldn’t stand to take another bite,” she wrote.","Meatless meats are generally a healthier choice than beef because they are cholesterol-free, plus they’re a good source of vitamins, minerals, protein, and fiber.","If meatless meat can help you stick to a plant-based diet, that in itself can lead to better health. Not only has red meat been linked to cancer, but studies show that people who ditch meat have lower blood pressure, lower average blood sugar, and lower cholesterol levels.","However, just because it’s plant-based doesn’t mean it’s health food. Most imitation meats are highly processed and contain high amounts of sodium (钠) compared to traditional beef.","These new generations of alternate meat get all the attention, but don’t forget about whole grains and vegetables. Beans are an especially excellent protein substitute. They’re nutritious, inexpensive, and far more sustainable than any of the processed meatless substitutes on the market today."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-5-q-51','cet4-2025-06-3-section-5',0,'choice','51. What can we expect of plant-based meats?','[{"key":"A","text":"An increasing interest in their analyses."},{"key":"B","text":"An enormous effort in their promotion."},{"key":"C","text":"A huge boost in their consumption."},{"key":"D","text":"A noticeable surge in their varieties."}]','C','参考答案 C，依据原文整理。首段预计植物肉市场到 2030 年大幅增长，并指出这一消费趋势近期不会放缓。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-5-q-52','cet4-2025-06-3-section-5',1,'choice','52. What do we learn about consumers buying Beyond Burger and Impossible Foods products?','[{"key":"A","text":"They are mostly non-vegetarians."},{"key":"B","text":"They are mostly animal-rights advocates."},{"key":"C","text":"Most of them refrain from eating meat for health reasons."},{"key":"D","text":"Most of them eat meatless meat to protect the environment."}]','A','参考答案 A，依据原文整理。第二段说购买这两家公司产品的消费者中超过九成也吃肉，说明多数不是素食者。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-5-q-53','cet4-2025-06-3-section-5',2,'choice','53. What can we conclude about Impossible Foods’ products from Joan Solsman’s remark?','[{"key":"A","text":"They more often appeal to meat-eaters."},{"key":"B","text":"They very much resemble animal meat."},{"key":"C","text":"Some have become its signature dishes."},{"key":"D","text":"Most of them are sold as true fake meat."}]','B','参考答案 B，依据原文整理。Joan Solsman 将产品称为 realistic fake meat，说明其味道和质感与动物肉非常相似。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-5-q-54','cet4-2025-06-3-section-5',3,'choice','54. Why can the habit of eating a plant-based diet lead to better health?','[{"key":"A","text":"It frees people from any known link to cancer."},{"key":"B","text":"It provides all the nutrients for staying healthy."},{"key":"C","text":"It helps maintain normal blood pressure and blood sugar."},{"key":"D","text":"It reduces various health risks posed by meat consumption."}]','D','参考答案 D，依据原文整理。第五段列出肉类与癌症的关联，以及不吃肉者血压、血糖和胆固醇较低的研究结果，用来说明减少相关健康风险。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-5-q-55','cet4-2025-06-3-section-5',4,'choice','55. What does the author recommend we eat at the end of the passage?','[{"key":"A","text":"Naturally produced foods."},{"key":"B","text":"Processed protein substitutes."},{"key":"C","text":"Red meats like traditional beef."},{"key":"D","text":"New generations of alternate meat."}]','A','参考答案 A，依据原文整理。末段提醒关注全谷物、蔬菜和豆类等天然食物，而非只关注加工的植物肉替代品。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-1-1','cet4-2025-06-3',400,0,'Plant-based meats are coming soon to a dinner table near you, but do they deserve a spot on your plate?','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-1-2','cet4-2025-06-3',400,1,'If you tried a vegetable burger years ago and dismissed it as rubbery and flavorless, it’s a good time to give meatless meat another chance.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-1-3','cet4-2025-06-3',400,2,'Newer varieties imitate the look, flavor, and texture of meat.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-1-4','cet4-2025-06-3',400,3,'Analysts don’t expect the meat-free movement to slow anytime soon; a 2021 report predicts the market will skyrocket to $74 billion by 2030—a 957 percent surge.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-2-1','cet4-2025-06-3',401,0,'Plant-based meats are no longer just for vegetarians.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-2-2','cet4-2025-06-3',401,1,'Companies such as Impossible Foods and Beyond Meat—the current superstars of the alternative protein sector—are pursuing consumers who enjoy meat but want to reduce their meat consumption for animal rights, health, or environmental reasons.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-2-3','cet4-2025-06-3',401,2,'So far, it’s a winning strategy: More than nine out of ten consumers who buy Beyond Burger and Impossible Foods products also eat meat.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-3-1','cet4-2025-06-3',402,0,'Many vegetarians don’t actually care for food that resembles meat.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-3-2','cet4-2025-06-3',402,1,'When reporter Joan Solsman, a longtime vegetarian, tried a dish from Impossible Foods, she felt so sick that she couldn’t finish it.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-3-3','cet4-2025-06-3',402,2,'“Maybe the best sign that Impossible Foods has cracked the code to realistic fake meat is that I couldn’t stand to take another bite,” she wrote.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-4-1','cet4-2025-06-3',403,0,'Meatless meats are generally a healthier choice than beef because they are cholesterol-free, plus they’re a good source of vitamins, minerals, protein, and fiber.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-5-1','cet4-2025-06-3',404,0,'If meatless meat can help you stick to a plant-based diet, that in itself can lead to better health.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-5-2','cet4-2025-06-3',404,1,'Not only has red meat been linked to cancer, but studies show that people who ditch meat have lower blood pressure, lower average blood sugar, and lower cholesterol levels.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-6-1','cet4-2025-06-3',405,0,'However, just because it’s plant-based doesn’t mean it’s health food.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-6-2','cet4-2025-06-3',405,1,'Most imitation meats are highly processed and contain high amounts of sodium (钠) compared to traditional beef.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-7-1','cet4-2025-06-3',406,0,'These new generations of alternate meat get all the attention, but don’t forget about whole grains and vegetables.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-7-2','cet4-2025-06-3',406,1,'Beans are an especially excellent protein substitute.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-3-section-5-sentence-7-3','cet4-2025-06-3',406,2,'They’re nutritious, inexpensive, and far more sustainable than any of the processed meatless substitutes on the market today.','cet4-2025-06-3-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-3-section-6','cet4-2025-06-3',5,'translation','翻译 · 汉译英','For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your answer on Answer Sheet 2.','["近年来，中国越来越多的城市着力打造“15 分钟便民生活圈（convenient living circles）”。 社区居民步行15 分钟就能享受到日常所需的公共服务。生活圈内建有便利店、公园、健身场地、图书馆、学校、社区食堂、诊所等。生活圈的建立能够为居民提供更加便利、舒适、友好、愉悦的生活环境，更好地满足城市居民多元化的日常生活服务需求，提升居民的生活品质和幸福感。"]','[]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-3-section-6-q-1','cet4-2025-06-3-section-6',0,'text','将上面的中文段落译成英文。','[]',NULL,'PDF 未提供参考译文；作答保留供自行核对。',10) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
