INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-12-1-section-2','cet4-2025-12-1',1,'cloze','选词填空（26–35）','In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list of choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each choice in the bank is identified by a letter: Please mark the corresponding letter for each item on Answer Sheet 2 with a single line through the centre. You may not use any of the words in the bank more than once.','["People tend to want as many choices as possible. They believe this will maximize their [26] ______ of making the best decision. But research shows that, when it comes to actually making a [27] ______ from all of these choices, people can become [28] ______ and avoid making a decision altogether. Even worse, when people finally do decide, they are generally less satisfied with their decision and feel more regretful over whatever choice they made.","Why does this happen? Research shows that when people choose from many options, they [29] ______ more in the decision, but feel less confident in their ability to decide well. In other words, when we are [30] ______ with more choices, making the “right” or “correct” decision begins to feel more [31] ______ and, at the same time, more difficult to do. This may contribute to the deep fear that we will make the wrong decision.","How can we solve this problem? I believe this fear could be tempered by putting decisions into perspective. It might help to remember that many of the choices you make, such as what to have for lunch, will not [32] ______ much in the future and that, even more important choices, like accepting a new job, can [33] ______ be changed. It could also help to [34] ______ these situations with clear guidelines and ideas of what you want from the [35] ______ of options, which can narrow the possible choices, and also make you more confident about your ability to make the right decision."]','["People tend to want as many choices as possible. They believe this will maximize their chance of making the best decision. But research shows that, when it comes to actually making a selection from all of these choices, people can become confused and avoid making a decision altogether. Even worse, when people finally do decide, they are generally less satisfied with their decision and feel more regretful over whatever choice they made.","Why does this happen? Research shows that when people choose from many options, they invest more in the decision, but feel less confident in their ability to decide well. In other words, when we are presented with more choices, making the “right” or “correct” decision begins to feel more crucial and, at the same time, more difficult to do. This may contribute to the deep fear that we will make the wrong decision.","How can we solve this problem? I believe this fear could be tempered by putting decisions into perspective. It might help to remember that many of the choices you make, such as what to have for lunch, will not matter much in the future and that, even more important choices, like accepting a new job, can ultimately be changed. It could also help to enter these situations with clear guidelines and ideas of what you want from the range of options, which can narrow the possible choices, and also make you more confident about your ability to make the right decision."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-2-q-26','cet4-2025-12-1-section-2',0,'choice','26. 第 26 空','[{"key":"A","text":"approximately"},{"key":"B","text":"case"},{"key":"C","text":"chance"},{"key":"D","text":"confused"},{"key":"E","text":"crucial"},{"key":"F","text":"deposited"},{"key":"G","text":"enter"},{"key":"H","text":"invest"},{"key":"I","text":"matter"},{"key":"J","text":"presented"},{"key":"K","text":"range"},{"key":"L","text":"regular"},{"key":"M","text":"seize"},{"key":"N","text":"selection"},{"key":"O","text":"ultimately"}]','C','参考答案 C，依据原文整理。maximize their chance of making the best decision 表示提高作出最佳决定的机会。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-2-q-27','cet4-2025-12-1-section-2',1,'choice','27. 第 27 空','[{"key":"A","text":"approximately"},{"key":"B","text":"case"},{"key":"C","text":"chance"},{"key":"D","text":"confused"},{"key":"E","text":"crucial"},{"key":"F","text":"deposited"},{"key":"G","text":"enter"},{"key":"H","text":"invest"},{"key":"I","text":"matter"},{"key":"J","text":"presented"},{"key":"K","text":"range"},{"key":"L","text":"regular"},{"key":"M","text":"seize"},{"key":"N","text":"selection"},{"key":"O","text":"ultimately"}]','N','参考答案 N，依据原文整理。making a selection from all of these choices 指从众多备选项中作出选择。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-2-q-28','cet4-2025-12-1-section-2',2,'choice','28. 第 28 空','[{"key":"A","text":"approximately"},{"key":"B","text":"case"},{"key":"C","text":"chance"},{"key":"D","text":"confused"},{"key":"E","text":"crucial"},{"key":"F","text":"deposited"},{"key":"G","text":"enter"},{"key":"H","text":"invest"},{"key":"I","text":"matter"},{"key":"J","text":"presented"},{"key":"K","text":"range"},{"key":"L","text":"regular"},{"key":"M","text":"seize"},{"key":"N","text":"selection"},{"key":"O","text":"ultimately"}]','D','参考答案 D，依据原文整理。become confused 表示选项过多让人困惑，因而干脆不作决定。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-2-q-29','cet4-2025-12-1-section-2',3,'choice','29. 第 29 空','[{"key":"A","text":"approximately"},{"key":"B","text":"case"},{"key":"C","text":"chance"},{"key":"D","text":"confused"},{"key":"E","text":"crucial"},{"key":"F","text":"deposited"},{"key":"G","text":"enter"},{"key":"H","text":"invest"},{"key":"I","text":"matter"},{"key":"J","text":"presented"},{"key":"K","text":"range"},{"key":"L","text":"regular"},{"key":"M","text":"seize"},{"key":"N","text":"selection"},{"key":"O","text":"ultimately"}]','H','参考答案 H，依据原文整理。invest more in the decision 指在决策上投入更多，与信心下降形成对比。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
