INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-2-q-32','cet4-2025-12-1-section-2',6,'choice','32. 第 32 空','[{"key":"A","text":"approximately"},{"key":"B","text":"case"},{"key":"C","text":"chance"},{"key":"D","text":"confused"},{"key":"E","text":"crucial"},{"key":"F","text":"deposited"},{"key":"G","text":"enter"},{"key":"H","text":"invest"},{"key":"I","text":"matter"},{"key":"J","text":"presented"},{"key":"K","text":"range"},{"key":"L","text":"regular"},{"key":"M","text":"seize"},{"key":"N","text":"selection"},{"key":"O","text":"ultimately"}]','I','参考答案 I，依据原文整理。will not matter much in the future 表示午餐等日常选择将来不会有太大影响。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
