INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-2-q-34','cet4-2025-12-1-section-2',8,'choice','34. 第 34 空','[{"key":"A","text":"approximately"},{"key":"B","text":"case"},{"key":"C","text":"chance"},{"key":"D","text":"confused"},{"key":"E","text":"crucial"},{"key":"F","text":"deposited"},{"key":"G","text":"enter"},{"key":"H","text":"invest"},{"key":"I","text":"matter"},{"key":"J","text":"presented"},{"key":"K","text":"range"},{"key":"L","text":"regular"},{"key":"M","text":"seize"},{"key":"N","text":"selection"},{"key":"O","text":"ultimately"}]','G','参考答案 G，依据原文整理。enter these situations with clear guidelines 表示带着明确的准则和目标面对决策情境。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-2-q-35','cet4-2025-12-1-section-2',9,'choice','35. 第 35 空','[{"key":"A","text":"approximately"},{"key":"B","text":"case"},{"key":"C","text":"chance"},{"key":"D","text":"confused"},{"key":"E","text":"crucial"},{"key":"F","text":"deposited"},{"key":"G","text":"enter"},{"key":"H","text":"invest"},{"key":"I","text":"matter"},{"key":"J","text":"presented"},{"key":"K","text":"range"},{"key":"L","text":"regular"},{"key":"M","text":"seize"},{"key":"N","text":"selection"},{"key":"O","text":"ultimately"}]','K','参考答案 K，依据原文整理。the range of options 指备选项的范围，明确目标有助于缩小选择范围。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-1-1','cet4-2025-12-1',100,0,'People tend to want as many choices as possible.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-1-2','cet4-2025-12-1',100,1,'They believe this will maximize their chance of making the best decision.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-1-3','cet4-2025-12-1',100,2,'But research shows that, when it comes to actually making a selection from all of these choices, people can become confused and avoid making a decision altogether.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-1-4','cet4-2025-12-1',100,3,'Even worse, when people finally do decide, they are generally less satisfied with their decision and feel more regretful over whatever choice they made.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-2-1','cet4-2025-12-1',101,0,'Why does this happen?','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-2-2','cet4-2025-12-1',101,1,'Research shows that when people choose from many options, they invest more in the decision, but feel less confident in their ability to decide well.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-2-3','cet4-2025-12-1',101,2,'In other words, when we are presented with more choices, making the “right” or “correct” decision begins to feel more crucial and, at the same time, more difficult to do.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-2-4','cet4-2025-12-1',101,3,'This may contribute to the deep fear that we will make the wrong decision.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-3-1','cet4-2025-12-1',102,0,'How can we solve this problem?','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-3-2','cet4-2025-12-1',102,1,'I believe this fear could be tempered by putting decisions into perspective.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-3-3','cet4-2025-12-1',102,2,'It might help to remember that many of the choices you make, such as what to have for lunch, will not matter much in the future and that, even more important choices, like accepting a new job, can ultimately be changed.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-2-sentence-3-4','cet4-2025-12-1',102,3,'It could also help to enter these situations with clear guidelines and ideas of what you want from the range of options, which can narrow the possible choices, and also make you more confident about your ability to make the right decision.','cet4-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-12-1-section-3','cet4-2025-12-1',2,'matching','长篇阅读（36–45）· The battle over bike lanes needs a mindset shift','In this section, you are going to read a passage with ten statements attached to it. Each statement contains information given in one of the paragraphs. Identify the paragraph from which the information is derived. You may choose a paragraph more than once. Each paragraph is marked with a letter. Answer the questions by marking the corresponding letter on Answer Sheet 2.','["[A] Five years ago, the city of Queens, New York, announced that it would be putting bike lanes onto a stretch of Skillman Ave—and removing 116 parking spots. Cyclists loved the plan, but local business owners got very angry. Taking out those parking spots, as they argued at protests and in letters to the city council, would ruin stores and restaurants along Skillman. \"Parking here is already a nightmare,\" one shouted at a protest rally.","[B] But the bike lanes were a done deal, and soon they were in place. Early this year, Jesse Coburn—an investigative writer with Streetsblog New York—wondered whether those predictions of economic collapse came true. So he asked the city''s Department of Finance to give him a few years’ worth of sales figures for that stretch of Skillman Ave. How had the businesses on that street fared?","[C] Quite well, it turns out. In the year after the bike lanes arrived, businesses on Skillman saw sales rise by 12 percent, compared to 3 percent for Queens in general. What''s more, that section of road saw new businesses open, while Queens overall had a net loss.","[D] The thing is, the actual merchants along Skillman? They didn''t believe it. When Coburn spoke to them and described what he''d found, only a few store owners admitted the lanes had helped. Many still insisted the lanes were killing their part of the city. And emotions ran hot: Someone scattered tacks (大头钉) on the bike lane.","[E] This little story turns out to be a fascinating glimpse at the challenges cities face as they try to update their urban infrastructure—to clean up the air, reduce greenhouse emissions, and speed up travel by making towns more bike-friendly. There''s a rising amount of data showing that installing bike lanes and making streets more pedestrian-friendly boosts the economic fortunes of a place. Removing cars and parking spots works. But the folks who run local businesses simply aren''t convinced, even when their own street performs. Given that sort of mess, can political fights over bike lanes ever end?","[F] In 2013, researchers at New York City''s Department of Transportation studied seven stretches of road that had installed bike lanes or created pedestrian-friendly areas. The city analyzed the data for businesses along those routes and found that by the third year, sales grew faster on five of the streets than in the district overall, on average—up to five times faster, in fact.","[G] Beyond New York, a survey of research from 23 cities found that bike lanes and pedestrian-friendly design didn''t hurt local retail and food stores. (\"Fears of disastrous consequences for local businesses are unfounded,\" the researchers concluded.) More recent work has shown roughly the same.","[H] The truth is that in fairly dense areas, bikes are more efficient at moving people around. You might lose one car driver''s business—but you gain shoppers who now can arrive more easily on bikes. “Cyclists and pedestrians are consumers too,\" notes Professor Susan Handy. Plus, streets redesigned for bikes and pedestrians tend to become more pleasant places to hang around, so “in a lot of cases, that''s created much nicer environments that are really good for those businesses.”","[I] Mom-and-pop shops are usually pretty quick at recognizing situations that will help their bottom lines. So why the blind spot here? Perhaps it''s that attention focuses on horror stories—and some merchants do get hit when bike lanes come in.","[J] I spoke to Cindy Hughes, a hairdresser (理发师) in Cambridge, Massachusetts. She said business fell by at least 40 percent when the city removed nearby parking to put in a bike lane. The majority of her customers drive, with many coming from nearby towns. Only a very few have shifted to cycling, and even those almost certainly won''t cycle in Boston''s snowy winters. So while Hughes supports bike lanes—“cyclists deserve to be safe”—she sees the parking loss as an existential risk. \"Look, 90 percent of my customers drive,\" she told me. “For our business, the bike lanes are way worse than Covid was.”","[K] For others, the pushback is cultural, says Henry Grabar, a writer for the Slate Magazine. Small business owners are frequently drivers who commute from other parts of the city by car, Grabar points out. They''re also often longtime locals. \"They tend to be people with deep roots in the city, who have hung around since before the neighborhood became what it is today,\" he adds. Driving around town in a car is so normal to them that cycling seems weird and unusual—despite its boost from Covid, when bike sales exploded by 75 percent.","[L] Psychology beats all! Who knew, right? The fierce divide between store owners and bike-lane advocates seems similar to our larger culture wars over climate change. If we''ve learned anything about culture wars, it''s that data isn''t much good at changing minds.","[M] When Janette Sadik-Khan was the head of New York City''s Transportation Department back in the early 2000s, she oversaw a rollout (推出) of bike lanes—and got angry blowback from residents and business owners who claimed there weren''t enough cyclists to justify installing lanes. Now, she notes ironically, the lanes are so full of activity that opponents have turned to claiming the problem is the opposite: There are too many cyclists getting in the way of cars.","[N] Maybe bike lanes will always be charged with emotion, until enough of the public is finally concerned about climate change—and it seems reckless (鲁莽的) to not have them.","[O] Crises, after all, have a way of opening people''s eyes to possibilities. During Covid, restaurants and cafés lost so much business that cities nationwide began allowing them to build curbside seating areas where people could sit, safely, in the open air. It greatly reduced parking—but because, well, shop owners didn''t see any way around it. Customers loved the outdoor seating so much that cities are making it permanent: A New York City study of several streets closed during Covid found store owners making more than before, and diners enjoying the outdoor lifestyle. If data won''t change minds, customers might."]','["Five years ago, the city of Queens, New York, announced that it would be putting bike lanes onto a stretch of Skillman Ave—and removing 116 parking spots. Cyclists loved the plan, but local business owners got very angry. Taking out those parking spots, as they argued at protests and in letters to the city council, would ruin stores and restaurants along Skillman. \"Parking here is already a nightmare,\" one shouted at a protest rally.","But the bike lanes were a done deal, and soon they were in place. Early this year, Jesse Coburn—an investigative writer with Streetsblog New York—wondered whether those predictions of economic collapse came true. So he asked the city''s Department of Finance to give him a few years’ worth of sales figures for that stretch of Skillman Ave. How had the businesses on that street fared?","Quite well, it turns out. In the year after the bike lanes arrived, businesses on Skillman saw sales rise by 12 percent, compared to 3 percent for Queens in general. What''s more, that section of road saw new businesses open, while Queens overall had a net loss.","The thing is, the actual merchants along Skillman? They didn''t believe it. When Coburn spoke to them and described what he''d found, only a few store owners admitted the lanes had helped. Many still insisted the lanes were killing their part of the city. And emotions ran hot: Someone scattered tacks (大头钉) on the bike lane.","This little story turns out to be a fascinating glimpse at the challenges cities face as they try to update their urban infrastructure—to clean up the air, reduce greenhouse emissions, and speed up travel by making towns more bike-friendly. There''s a rising amount of data showing that installing bike lanes and making streets more pedestrian-friendly boosts the economic fortunes of a place. Removing cars and parking spots works. But the folks who run local businesses simply aren''t convinced, even when their own street performs. Given that sort of mess, can political fights over bike lanes ever end?","In 2013, researchers at New York City''s Department of Transportation studied seven stretches of road that had installed bike lanes or created pedestrian-friendly areas. The city analyzed the data for businesses along those routes and found that by the third year, sales grew faster on five of the streets than in the district overall, on average—up to five times faster, in fact.","Beyond New York, a survey of research from 23 cities found that bike lanes and pedestrian-friendly design didn''t hurt local retail and food stores. (\"Fears of disastrous consequences for local businesses are unfounded,\" the researchers concluded.) More recent work has shown roughly the same.","The truth is that in fairly dense areas, bikes are more efficient at moving people around. You might lose one car driver''s business—but you gain shoppers who now can arrive more easily on bikes. “Cyclists and pedestrians are consumers too,\" notes Professor Susan Handy. Plus, streets redesigned for bikes and pedestrians tend to become more pleasant places to hang around, so “in a lot of cases, that''s created much nicer environments that are really good for those businesses.”","Mom-and-pop shops are usually pretty quick at recognizing situations that will help their bottom lines. So why the blind spot here? Perhaps it''s that attention focuses on horror stories—and some merchants do get hit when bike lanes come in.","I spoke to Cindy Hughes, a hairdresser (理发师) in Cambridge, Massachusetts. She said business fell by at least 40 percent when the city removed nearby parking to put in a bike lane. The majority of her customers drive, with many coming from nearby towns. Only a very few have shifted to cycling, and even those almost certainly won''t cycle in Boston''s snowy winters. So while Hughes supports bike lanes—“cyclists deserve to be safe”—she sees the parking loss as an existential risk. \"Look, 90 percent of my customers drive,\" she told me. “For our business, the bike lanes are way worse than Covid was.”","For others, the pushback is cultural, says Henry Grabar, a writer for the Slate Magazine. Small business owners are frequently drivers who commute from other parts of the city by car, Grabar points out. They''re also often longtime locals. \"They tend to be people with deep roots in the city, who have hung around since before the neighborhood became what it is today,\" he adds. Driving around town in a car is so normal to them that cycling seems weird and unusual—despite its boost from Covid, when bike sales exploded by 75 percent.","Psychology beats all! Who knew, right? The fierce divide between store owners and bike-lane advocates seems similar to our larger culture wars over climate change. If we''ve learned anything about culture wars, it''s that data isn''t much good at changing minds.","When Janette Sadik-Khan was the head of New York City''s Transportation Department back in the early 2000s, she oversaw a rollout (推出) of bike lanes—and got angry blowback from residents and business owners who claimed there weren''t enough cyclists to justify installing lanes. Now, she notes ironically, the lanes are so full of activity that opponents have turned to claiming the problem is the opposite: There are too many cyclists getting in the way of cars.","Maybe bike lanes will always be charged with emotion, until enough of the public is finally concerned about climate change—and it seems reckless (鲁莽的) to not have them.","Crises, after all, have a way of opening people''s eyes to possibilities. During Covid, restaurants and cafés lost so much business that cities nationwide began allowing them to build curbside seating areas where people could sit, safely, in the open air. It greatly reduced parking—but because, well, shop owners didn''t see any way around it. Customers loved the outdoor seating so much that cities are making it permanent: A New York City study of several streets closed during Covid found store owners making more than before, and diners enjoying the outdoor lifestyle. If data won''t change minds, customers might."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-36','cet4-2025-12-1-section-3',0,'choice','36. An increasing amount of data indicates that installing bike lanes raises local business revenues.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','E','参考答案 E，依据原文整理。E 段指出越来越多的数据表明，自行车道和适合步行的街道有利于当地经济。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-37','cet4-2025-12-1-section-3',1,'choice','37. According to a magazine writer, some small business owners''resistance to bike lanes arises from cultural factors.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','K','参考答案 K，依据原文整理。K 段引用杂志作者 Henry Grabar，说明部分小商家的反对来自习惯开车的文化因素。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-38','cet4-2025-12-1-section-3',2,'choice','38. A stretch of Skillman Ave witnessed not only a big increase in sales but also the opening of new businesses.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','C','参考答案 C，依据原文整理。C 段说 Skillman 的销售额增长 12%，同时出现了新开业的商家。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-39','cet4-2025-12-1-section-3',3,'choice','39. When people have no way out in crises, they are more likely to embrace changes.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','O','参考答案 O，依据原文整理。O 段用疫情期间允许路边露天座位的例子，说明危机让人接受新的可能性。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-40','cet4-2025-12-1-section-3',4,'choice','40. According to one survey, city design with bike lanes and pedestrian space did not negatively impact local businesses.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','G','参考答案 G，依据原文整理。G 段介绍对 23 个城市研究的综述，认为自行车道和步行空间并未损害当地零售及餐饮业。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-41','cet4-2025-12-1-section-3',5,'choice','41. Despite increased business activity on Skillman Ave, many store owners insisted the bike lanes were destroying their area.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','D','参考答案 D，依据原文整理。D 段说即使得知销售增长，许多店主仍坚持认为自行车道在破坏街区。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-42','cet4-2025-12-1-section-3',6,'choice','42. In a war of culture, data does not help much in changing people''s minds.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','L','参考答案 L，依据原文整理。L 段将争论比作文化战争，并指出数据并不善于改变人们的想法。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-43','cet4-2025-12-1-section-3',7,'choice','43. A businesswoman said her business dropped sharply when parking space gave way to a bike lane, because most of her customers came by car.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','J','参考答案 J，依据原文整理。J 段中理发师说附近停车位改为自行车道后生意下降至少 40%，而 90% 的顾客开车来。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-44','cet4-2025-12-1-section-3',8,'choice','44. Local business owners on Skillman Ave argued that their businesses would be ruined when parking spots were replaced by bike lanes.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','A','参考答案 A，依据原文整理。A 段介绍商家最初反对取消停车位，并声称这会毁掉街上的商店和餐馆。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-3-q-45','cet4-2025-12-1-section-3',9,'choice','45. People may find it more pleasant to wander around streets redesigned for cycling and walking.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"},{"key":"N","text":"段落 N"},{"key":"O","text":"段落 O"}]','H','参考答案 H，依据原文整理。H 段说为骑行和步行重新设计的街道更宜人，顾客更愿意逗留。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-1-1','cet4-2025-12-1',200,0,'Five years ago, the city of Queens, New York, announced that it would be putting bike lanes onto a stretch of Skillman Ave—and removing 116 parking spots.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-1-2','cet4-2025-12-1',200,1,'Cyclists loved the plan, but local business owners got very angry.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-1-3','cet4-2025-12-1',200,2,'Taking out those parking spots, as they argued at protests and in letters to the city council, would ruin stores and restaurants along Skillman.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-1-4','cet4-2025-12-1',200,3,'"Parking here is already a nightmare," one shouted at a protest rally.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-2-1','cet4-2025-12-1',201,0,'But the bike lanes were a done deal, and soon they were in place.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-2-2','cet4-2025-12-1',201,1,'Early this year, Jesse Coburn—an investigative writer with Streetsblog New York—wondered whether those predictions of economic collapse came true.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-2-3','cet4-2025-12-1',201,2,'So he asked the city''s Department of Finance to give him a few years’ worth of sales figures for that stretch of Skillman Ave.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-2-4','cet4-2025-12-1',201,3,'How had the businesses on that street fared?','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-3-1','cet4-2025-12-1',202,0,'Quite well, it turns out.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-3-2','cet4-2025-12-1',202,1,'In the year after the bike lanes arrived, businesses on Skillman saw sales rise by 12 percent, compared to 3 percent for Queens in general.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-3-3','cet4-2025-12-1',202,2,'What''s more, that section of road saw new businesses open, while Queens overall had a net loss.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-4-1','cet4-2025-12-1',203,0,'The thing is, the actual merchants along Skillman?','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-4-2','cet4-2025-12-1',203,1,'They didn''t believe it.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-4-3','cet4-2025-12-1',203,2,'When Coburn spoke to them and described what he''d found, only a few store owners admitted the lanes had helped.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-4-4','cet4-2025-12-1',203,3,'Many still insisted the lanes were killing their part of the city.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-4-5','cet4-2025-12-1',203,4,'And emotions ran hot: Someone scattered tacks (大头钉) on the bike lane.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-5-1','cet4-2025-12-1',204,0,'This little story turns out to be a fascinating glimpse at the challenges cities face as they try to update their urban infrastructure—to clean up the air, reduce greenhouse emissions, and speed up travel by making towns more bike-friendly.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-5-2','cet4-2025-12-1',204,1,'There''s a rising amount of data showing that installing bike lanes and making streets more pedestrian-friendly boosts the economic fortunes of a place.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-5-3','cet4-2025-12-1',204,2,'Removing cars and parking spots works.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-5-4','cet4-2025-12-1',204,3,'But the folks who run local businesses simply aren''t convinced, even when their own street performs.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-5-5','cet4-2025-12-1',204,4,'Given that sort of mess, can political fights over bike lanes ever end?','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-6-1','cet4-2025-12-1',205,0,'In 2013, researchers at New York City''s Department of Transportation studied seven stretches of road that had installed bike lanes or created pedestrian-friendly areas.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-6-2','cet4-2025-12-1',205,1,'The city analyzed the data for businesses along those routes and found that by the third year, sales grew faster on five of the streets than in the district overall, on average—up to five times faster, in fact.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-7-1','cet4-2025-12-1',206,0,'Beyond New York, a survey of research from 23 cities found that bike lanes and pedestrian-friendly design didn''t hurt local retail and food stores. ("Fears of disastrous consequences for local businesses are unfounded," the researchers concluded.) More recent work has shown roughly the same.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-8-1','cet4-2025-12-1',207,0,'The truth is that in fairly dense areas, bikes are more efficient at moving people around.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-8-2','cet4-2025-12-1',207,1,'You might lose one car driver''s business—but you gain shoppers who now can arrive more easily on bikes.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-8-3','cet4-2025-12-1',207,2,'“Cyclists and pedestrians are consumers too," notes Professor Susan Handy.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-8-4','cet4-2025-12-1',207,3,'Plus, streets redesigned for bikes and pedestrians tend to become more pleasant places to hang around, so “in a lot of cases, that''s created much nicer environments that are really good for those businesses.”','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-9-1','cet4-2025-12-1',208,0,'Mom-and-pop shops are usually pretty quick at recognizing situations that will help their bottom lines.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-9-2','cet4-2025-12-1',208,1,'So why the blind spot here?','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-9-3','cet4-2025-12-1',208,2,'Perhaps it''s that attention focuses on horror stories—and some merchants do get hit when bike lanes come in.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-10-1','cet4-2025-12-1',209,0,'I spoke to Cindy Hughes, a hairdresser (理发师) in Cambridge, Massachusetts.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-10-2','cet4-2025-12-1',209,1,'She said business fell by at least 40 percent when the city removed nearby parking to put in a bike lane.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-10-3','cet4-2025-12-1',209,2,'The majority of her customers drive, with many coming from nearby towns.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-10-4','cet4-2025-12-1',209,3,'Only a very few have shifted to cycling, and even those almost certainly won''t cycle in Boston''s snowy winters.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-10-5','cet4-2025-12-1',209,4,'So while Hughes supports bike lanes—“cyclists deserve to be safe”—she sees the parking loss as an existential risk.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-10-6','cet4-2025-12-1',209,5,'"Look, 90 percent of my customers drive," she told me.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-10-7','cet4-2025-12-1',209,6,'“For our business, the bike lanes are way worse than Covid was.”','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-11-1','cet4-2025-12-1',210,0,'For others, the pushback is cultural, says Henry Grabar, a writer for the Slate Magazine.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-11-2','cet4-2025-12-1',210,1,'Small business owners are frequently drivers who commute from other parts of the city by car, Grabar points out.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-11-3','cet4-2025-12-1',210,2,'They''re also often longtime locals.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-11-4','cet4-2025-12-1',210,3,'"They tend to be people with deep roots in the city, who have hung around since before the neighborhood became what it is today," he adds.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-11-5','cet4-2025-12-1',210,4,'Driving around town in a car is so normal to them that cycling seems weird and unusual—despite its boost from Covid, when bike sales exploded by 75 percent.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-12-1','cet4-2025-12-1',211,0,'Psychology beats all!','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-12-2','cet4-2025-12-1',211,1,'Who knew, right?','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-12-3','cet4-2025-12-1',211,2,'The fierce divide between store owners and bike-lane advocates seems similar to our larger culture wars over climate change.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-12-4','cet4-2025-12-1',211,3,'If we''ve learned anything about culture wars, it''s that data isn''t much good at changing minds.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-13-1','cet4-2025-12-1',212,0,'When Janette Sadik-Khan was the head of New York City''s Transportation Department back in the early 2000s, she oversaw a rollout (推出) of bike lanes—and got angry blowback from residents and business owners who claimed there weren''t enough cyclists to justify installing lanes.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-13-2','cet4-2025-12-1',212,1,'Now, she notes ironically, the lanes are so full of activity that opponents have turned to claiming the problem is the opposite: There are too many cyclists getting in the way of cars.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-14-1','cet4-2025-12-1',213,0,'Maybe bike lanes will always be charged with emotion, until enough of the public is finally concerned about climate change—and it seems reckless (鲁莽的) to not have them.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-15-1','cet4-2025-12-1',214,0,'Crises, after all, have a way of opening people''s eyes to possibilities.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-15-2','cet4-2025-12-1',214,1,'During Covid, restaurants and cafés lost so much business that cities nationwide began allowing them to build curbside seating areas where people could sit, safely, in the open air.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-15-3','cet4-2025-12-1',214,2,'It greatly reduced parking—but because, well, shop owners didn''t see any way around it.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-15-4','cet4-2025-12-1',214,3,'Customers loved the outdoor seating so much that cities are making it permanent: A New York City study of several streets closed during Covid found store owners making more than before, and diners enjoying the outdoor lifestyle.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-3-sentence-15-5','cet4-2025-12-1',214,4,'If data won''t change minds, customers might.','cet4-2025-12-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-12-1-section-4','cet4-2025-12-1',3,'reading','仔细阅读 · Passage One（46–50）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["All living organisms on Earth are exposed to a 24-hour day-night cycle. This cycle is the reason why people rest at night and are active during the day. Consequently, all human body functions also follow this daily rhythm, and the timing of behaviors like exercise or food intake can significantly influence your health. For example, eating at night can lead to weight gain over time because food intake at night leads to increased fat storage.","Many drug targets in the body follow a 24-hour cycle, too. This means that the specific proteins a drug is designed to modify can react differently to the medicine over the course of a 24-hour time period. Because how the body responds to a drug can differ depending on the time it is taken, it logically follows that taking medicines at specific times could help increase their effectiveness and reduce unwanted side effects.","When doctors prescribe medicine for people, they rarely consider the best time to take it. There are two main reasons for that oversight. First, many physicians are not aware that some drugs work better during a specific time of the day. And second, most drugs have not been studied for possible different effects during a 24-hour cycle. Therefore, patients are directed to take most drugs during the morning or evening primarily to ensure compliance.","Over 50 years ago, researchers found that the cholesterol drug simvastatin is more effective at lowering cholesterol levels when taken at night rather than during the day. This is because the liver enzyme (酶) these drugs target is more active at night.","Taking medicine at the wrong time can even cause harm. My colleagues and I wondered whether midazolam, the most common sedative (镇静剂) used in surgical procedures worldwide, might interfere with the internal clock that protects the heart at night. Currently, there are no guidelines regarding when midazolam should be administered.","More research is needed to determine the best times to administer treatments for different diseases. I believe taking drug timing into account could help make treatments more effective and help more people worldwide."]','["All living organisms on Earth are exposed to a 24-hour day-night cycle. This cycle is the reason why people rest at night and are active during the day. Consequently, all human body functions also follow this daily rhythm, and the timing of behaviors like exercise or food intake can significantly influence your health. For example, eating at night can lead to weight gain over time because food intake at night leads to increased fat storage.","Many drug targets in the body follow a 24-hour cycle, too. This means that the specific proteins a drug is designed to modify can react differently to the medicine over the course of a 24-hour time period. Because how the body responds to a drug can differ depending on the time it is taken, it logically follows that taking medicines at specific times could help increase their effectiveness and reduce unwanted side effects.","When doctors prescribe medicine for people, they rarely consider the best time to take it. There are two main reasons for that oversight. First, many physicians are not aware that some drugs work better during a specific time of the day. And second, most drugs have not been studied for possible different effects during a 24-hour cycle. Therefore, patients are directed to take most drugs during the morning or evening primarily to ensure compliance.","Over 50 years ago, researchers found that the cholesterol drug simvastatin is more effective at lowering cholesterol levels when taken at night rather than during the day. This is because the liver enzyme (酶) these drugs target is more active at night.","Taking medicine at the wrong time can even cause harm. My colleagues and I wondered whether midazolam, the most common sedative (镇静剂) used in surgical procedures worldwide, might interfere with the internal clock that protects the heart at night. Currently, there are no guidelines regarding when midazolam should be administered.","More research is needed to determine the best times to administer treatments for different diseases. I believe taking drug timing into account could help make treatments more effective and help more people worldwide."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-4-q-46','cet4-2025-12-1-section-4',0,'choice','46. What do we learn from the passage about the timing of our behaviors?','[{"key":"A","text":"It has a considerable impact on our health."},{"key":"B","text":"It confines us to a 24-hour day-night cycle."},{"key":"C","text":"It requires us to follow a particular rhythm."},{"key":"D","text":"It holds the key to all human body functions."}]','A','参考答案 A，依据原文整理。首段说运动、进食等行为发生的时间会显著影响健康。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-4-q-47','cet4-2025-12-1-section-4',1,'choice','47. What does the author say about the proteins in our body?','[{"key":"A","text":"They can modify the effects of medicines in different ways."},{"key":"B","text":"They can reduce unwanted side effects of certain medicines."},{"key":"C","text":"Their reaction to medicines changes during the day-night cycle."},{"key":"D","text":"Their design determines how differently they react to medicines."}]','C','参考答案 C，依据原文整理。第二段说药物作用的蛋白质在 24 小时内对药物的反应可能不同。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-4-q-48','cet4-2025-12-1-section-4',2,'choice','48. What do doctors do when prescribing medicine for people?','[{"key":"A","text":"They give little thought to the time of taking it for maximum effect."},{"key":"B","text":"They rarely consider which medicine works better for which patient."},{"key":"C","text":"They tell patients its possible side effects during a period of 24 hours."},{"key":"D","text":"They tell patients to comply with the directions of drug manufacturers."}]','A','参考答案 A，依据原文整理。第三段明确说医生开药时很少考虑最佳服药时间。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-4-q-49','cet4-2025-12-1-section-4',3,'choice','49. Why do doctors advise patients to take most drugs in the morning or in the evening?','[{"key":"A","text":"To discourage them from making complaints."},{"key":"B","text":"To ensure they take the drugs as instructed."},{"key":"C","text":"To comply with new research findings strictly."},{"key":"D","text":"To guarantee the maximum effect of the drugs."}]','B','参考答案 B，依据原文整理。第三段末句说通常安排早晚服药，主要是为了确保患者依从医嘱。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-4-q-50','cet4-2025-12-1-section-4',4,'choice','50. What does the author suggest near the end of the passage?','[{"key":"A","text":"Considering drug-taking timing when prescribing drugs for patients."},{"key":"B","text":"Making treatments less complex by taking drug timing into account."},{"key":"C","text":"Conducting more studies to find out the best timing for treating different diseases."},{"key":"D","text":"Finding out the most effective drugs for treating diseases through further research."}]','C','参考答案 C，依据原文整理。末段明确指出需要更多研究来确定不同疾病的最佳治疗时间。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-1-1','cet4-2025-12-1',300,0,'All living organisms on Earth are exposed to a 24-hour day-night cycle.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-1-2','cet4-2025-12-1',300,1,'This cycle is the reason why people rest at night and are active during the day.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-1-3','cet4-2025-12-1',300,2,'Consequently, all human body functions also follow this daily rhythm, and the timing of behaviors like exercise or food intake can significantly influence your health.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-1-4','cet4-2025-12-1',300,3,'For example, eating at night can lead to weight gain over time because food intake at night leads to increased fat storage.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-2-1','cet4-2025-12-1',301,0,'Many drug targets in the body follow a 24-hour cycle, too.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-2-2','cet4-2025-12-1',301,1,'This means that the specific proteins a drug is designed to modify can react differently to the medicine over the course of a 24-hour time period.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-2-3','cet4-2025-12-1',301,2,'Because how the body responds to a drug can differ depending on the time it is taken, it logically follows that taking medicines at specific times could help increase their effectiveness and reduce unwanted side effects.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-3-1','cet4-2025-12-1',302,0,'When doctors prescribe medicine for people, they rarely consider the best time to take it.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-3-2','cet4-2025-12-1',302,1,'There are two main reasons for that oversight.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-3-3','cet4-2025-12-1',302,2,'First, many physicians are not aware that some drugs work better during a specific time of the day.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-3-4','cet4-2025-12-1',302,3,'And second, most drugs have not been studied for possible different effects during a 24-hour cycle.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-3-5','cet4-2025-12-1',302,4,'Therefore, patients are directed to take most drugs during the morning or evening primarily to ensure compliance.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-4-1','cet4-2025-12-1',303,0,'Over 50 years ago, researchers found that the cholesterol drug simvastatin is more effective at lowering cholesterol levels when taken at night rather than during the day.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-4-2','cet4-2025-12-1',303,1,'This is because the liver enzyme (酶) these drugs target is more active at night.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-5-1','cet4-2025-12-1',304,0,'Taking medicine at the wrong time can even cause harm.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-5-2','cet4-2025-12-1',304,1,'My colleagues and I wondered whether midazolam, the most common sedative (镇静剂) used in surgical procedures worldwide, might interfere with the internal clock that protects the heart at night.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-5-3','cet4-2025-12-1',304,2,'Currently, there are no guidelines regarding when midazolam should be administered.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-6-1','cet4-2025-12-1',305,0,'More research is needed to determine the best times to administer treatments for different diseases.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-1-section-4-sentence-6-2','cet4-2025-12-1',305,1,'I believe taking drug timing into account could help make treatments more effective and help more people worldwide.','cet4-2025-12-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-12-1-section-5','cet4-2025-12-1',4,'reading','仔细阅读 · Passage Two（51–55）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["Katharine Abraham, an economics professor, was chatting with her hairdresser (理发师) about retirement plans. The economist said she plans to continue working because she wants to. The hairdresser agreed but for a different reason: She needs the money.","Both scenarios (情况) are contributing to a big increase in the number of people in the US working into their 70s. Over the past 20 years, the share of Americans working in their 70s has risen from less than 10% to nearly 15%.","In addition to people being healthier and living much longer, economists say that a combination of financial considerations such as years of slow rise in real wages and a shift away from traditional pensions in the private sector are some of the reasons people delay retirement. The decline of manufacturing and the increase in the number of people working in less labor-intensive occupations also has contributed to the trend, says Abraham, who researches work and retirement decisions of older Americans.","\"Which matters more depends on what your history up until that point has been in the type of work you''re doing,\" Abraham says.","The overall trend is hitting Americans of all different levels of educational attainment, although the percentages vary by category. The share of Americans with bachelor''s degrees who were working into their 70s reached nearly 20% in 2018. For those with a high school degree or less, the proportion of those working in their 70s had risen to around 10%, while those with some college education were in the middle at around 15%.","Martin Neil Baily, an economist who is leading a research project on retirement security, notes that quitting a career can lead to feelings of isolation and loneliness, particularly for men. He suggests that many college-educated workers are choosing to stay in the labor force more for social benefits than for financial reasons. They''re also more likely to be in professional occupations where they tend to enjoy their work more.","Workers in more physical jobs, meanwhile, may be more likely to look forward to retiring, Baily says, suggesting those who stay on are more likely doing so for financial reasons."]','["Katharine Abraham, an economics professor, was chatting with her hairdresser (理发师) about retirement plans. The economist said she plans to continue working because she wants to. The hairdresser agreed but for a different reason: She needs the money.","Both scenarios (情况) are contributing to a big increase in the number of people in the US working into their 70s. Over the past 20 years, the share of Americans working in their 70s has risen from less than 10% to nearly 15%.","In addition to people being healthier and living much longer, economists say that a combination of financial considerations such as years of slow rise in real wages and a shift away from traditional pensions in the private sector are some of the reasons people delay retirement. The decline of manufacturing and the increase in the number of people working in less labor-intensive occupations also has contributed to the trend, says Abraham, who researches work and retirement decisions of older Americans.","\"Which matters more depends on what your history up until that point has been in the type of work you''re doing,\" Abraham says.","The overall trend is hitting Americans of all different levels of educational attainment, although the percentages vary by category. The share of Americans with bachelor''s degrees who were working into their 70s reached nearly 20% in 2018. For those with a high school degree or less, the proportion of those working in their 70s had risen to around 10%, while those with some college education were in the middle at around 15%.","Martin Neil Baily, an economist who is leading a research project on retirement security, notes that quitting a career can lead to feelings of isolation and loneliness, particularly for men. He suggests that many college-educated workers are choosing to stay in the labor force more for social benefits than for financial reasons. They''re also more likely to be in professional occupations where they tend to enjoy their work more.","Workers in more physical jobs, meanwhile, may be more likely to look forward to retiring, Baily says, suggesting those who stay on are more likely doing so for financial reasons."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-5-q-51','cet4-2025-12-1-section-5',0,'choice','51. What do we learn from the passage about the economics professor and her hairdresser?','[{"key":"A","text":"They differ in their reasons for continuing to work."},{"key":"B","text":"They are both committed to working into their 70s."},{"key":"C","text":"They are happy about their current financial situation."},{"key":"D","text":"They hold different views about postponing retirement."}]','A','参考答案 A，依据原文整理。首段中教授因为愿意而继续工作，理发师则因为需要钱，两人的原因不同。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-5-q-52','cet4-2025-12-1-section-5',1,'choice','52. What is one of the reasons for people to delay retirement?','[{"key":"A","text":"More and more people have switched to less intellectually challenging jobs."},{"key":"B","text":"The number of jobs suitable for older people has increased in the private sector."},{"key":"C","text":"The rate of wage increase in terms of purchasing power has slowed down for years."},{"key":"D","text":"More and more people in the workplace find it hard to rely on traditional pensions."}]','C','参考答案 C，依据原文整理。第三段把多年实际工资缓慢上涨列为延迟退休的经济因素。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-5-q-53','cet4-2025-12-1-section-5',2,'choice','53. What is the general trend in people delaying retirement?','[{"key":"A","text":"The higher their earnings, the more likely they are tempted to delay retirement."},{"key":"B","text":"Those who have more job satisfaction tend to retire later than those who have less."},{"key":"C","text":"More men than women are likely to stay in the labor force until their late seventies."},{"key":"D","text":"The higher their educational level, the more likely they are to delay retirement."}]','D','参考答案 D，依据原文整理。按学历列出的数据分别约为 20%、15% 和 10%，说明学历越高，70 多岁仍工作的人比例越大。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-5-q-54','cet4-2025-12-1-section-5',3,'choice','54. What is the chief reason for college-educated workers delaying retirement according to an economist?','[{"key":"A","text":"Enjoying financial security."},{"key":"B","text":"Staying connected socially."},{"key":"C","text":"Contributing more professionally."},{"key":"D","text":"Increasing social security payments"}]','B','参考答案 B，依据原文整理。经济学家指出许多大学毕业者继续工作主要为了保持社会联系，而非经济需要。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-1-section-5-q-55','cet4-2025-12-1-section-5',4,'choice','55. What does the passage say about people doing manual work?','[{"key":"A","text":"They are eager to enjoy life after retiring."},{"key":"B","text":"They are likely to have financial troubles."},{"key":"C","text":"They generally don''t enjoy doing it."},{"key":"D","text":"They tend to anticipate retirement."}]','D','参考答案 D，依据原文整理。末段说从事体力劳动的人更可能期待退休，继续工作者往往出于经济原因。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
