INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-12-1','cet4-2026-06-1',311,0,'On the other hand, advocates of organic farming argue yields and efficiency could be significantly improved if the food industry devoted as much research and money to organic farming as it does conventional agriculture.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-1-section-5','cet4-2026-06-1',4,'reading','仔细阅读 · Passage Two（51–55）','阅读文章，为每题选择一个最佳答案。','["It is still controversial whether we are fundamentally generous or selfish and whether these tendencies are shaped by our genes or environment.","Some evidence points to humans being born cooperative. At later stages in life we routinely work together to reach goals and help out in times of need.","Yet instances of selfish behavior are also plenty. One recent study tested people’s willingness to set aside selfish interests to reach a greater good. It found that being selfish was more advantageous than cooperating. The benefit may be short-lived, however. Another study showed that players who cooperated did better in the long run.","It seems that human nature supports both pro-social and selfish traits (特征). Genetic studies have made some progress toward identifying their biological roots. By comparing identical twins, who share nearly 100 percent of their genes, and non-identical twins, who share about half, researchers have found overwhelming evidence for genetic effects on behaviors. In these twin studies, identical and non-identical twins are asked, for example, to split a sum of money with a peer. Such studies often also rely on careful psychological assessments and DNA analysis.","Other work highlights specific genes as key players. My colleagues and I recently identified a gene linked to altruistic (利他的) behavior and found that a particular variant of it was associated with more selfish behavior in preschoolers.","According to evolutionary scientists, cooperative behavior may have evolved first among relatives to promote the continuation of their genetic line. As communities diversified, mutual support could have broadened to include individuals not linked by blood. Another possibility is that humans cooperate to gain some advantage, such as boosting reputation. Finally, evolutionary processes take place at the group level. Groups of highly cooperative individuals have higher chances of survival because they can work together to reach goals that are unattainable to less cooperative groups.","Yet almost no behavior is entirely genetic, even among identical twins. Culture, schooling and parenting are important determinants of cooperation. Thus, the degree to which we act cooperatively or selfishly is unique to each individual and depends on a variety of genetic and environmental influences."]','["It is still controversial whether we are fundamentally generous or selfish and whether these tendencies are shaped by our genes or environment.","Some evidence points to humans being born cooperative. At later stages in life we routinely work together to reach goals and help out in times of need.","Yet instances of selfish behavior are also plenty. One recent study tested people’s willingness to set aside selfish interests to reach a greater good. It found that being selfish was more advantageous than cooperating. The benefit may be short-lived, however. Another study showed that players who cooperated did better in the long run.","It seems that human nature supports both pro-social and selfish traits (特征). Genetic studies have made some progress toward identifying their biological roots. By comparing identical twins, who share nearly 100 percent of their genes, and non-identical twins, who share about half, researchers have found overwhelming evidence for genetic effects on behaviors. In these twin studies, identical and non-identical twins are asked, for example, to split a sum of money with a peer. Such studies often also rely on careful psychological assessments and DNA analysis.","Other work highlights specific genes as key players. My colleagues and I recently identified a gene linked to altruistic (利他的) behavior and found that a particular variant of it was associated with more selfish behavior in preschoolers.","According to evolutionary scientists, cooperative behavior may have evolved first among relatives to promote the continuation of their genetic line. As communities diversified, mutual support could have broadened to include individuals not linked by blood. Another possibility is that humans cooperate to gain some advantage, such as boosting reputation. Finally, evolutionary processes take place at the group level. Groups of highly cooperative individuals have higher chances of survival because they can work together to reach goals that are unattainable to less cooperative groups.","Yet almost no behavior is entirely genetic, even among identical twins. Culture, schooling and parenting are important determinants of cooperation. Thus, the degree to which we act cooperatively or selfishly is unique to each individual and depends on a variety of genetic and environmental influences."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-51','cet4-2026-06-1-section-5',0,'choice','51. What is the finding of one recent study about being selfish?','[{"key":"A","text":"It may bring certain benefits in the short term."},{"key":"B","text":"It usually yields more disadvantages than advantages."},{"key":"C","text":"It serves individual interest rather than a collective’s."},{"key":"D","text":"It may give way to cooperating in the long run."}]','A','参考答案 A。第三段先说自私更有利，随后指出这种收益可能短暂，而合作长期表现更好。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-52','cet4-2026-06-1-section-5',1,'choice','52. What have researchers found by studying identical and non-identical twins?','[{"key":"A","text":"They are overwhelmingly different in the amounts of genes."},{"key":"B","text":"One’s behavior is largely determined by their genetic traits."},{"key":"C","text":"One’s biological roots can be identified by their genes."},{"key":"D","text":"They differ from each other in their behavior patterns."}]','B','参考答案 B。双胞胎研究段落强调基因对行为的影响；末段另补充文化、学校和家庭等环境因素。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-53','cet4-2026-06-1-section-5',2,'choice','53. What did the author and colleagues identify in their recent research?','[{"key":"A","text":"A gene-related selfish behavior in preschool children."},{"key":"B","text":"Key factors that determine one’s altruistic behavior."},{"key":"C","text":"A specific gene associated with altruistic behavior."},{"key":"D","text":"Roles played by genes in shaping one’s character."}]','C','参考答案 C。作者与同事发现一种与利他行为相关的特定基因，并进一步讨论它的变体。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-54','cet4-2026-06-1-section-5',3,'choice','54. What do we learn from evolutionary scientists about cooperative behavior?','[{"key":"A","text":"It may have initially originated in individuals linked by blood."},{"key":"B","text":"It may have caused the diversification of communities."},{"key":"C","text":"It helps to build relationships among blood-related people."},{"key":"D","text":"It guarantees the achievement of goals otherwise unattainable."}]','A','参考答案 A。进化研究段落提出合作可能最先在亲属之间出现，以延续其遗传谱系。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-55','cet4-2026-06-1-section-5',4,'choice','55. What can we infer from the last paragraph?','[{"key":"A","text":"Cooperative behavior is evident among identical twins."},{"key":"B","text":"One is born either cooperative or non-cooperative."},{"key":"C","text":"Genes determine one’s tendency to cooperate."},{"key":"D","text":"Cooperative behavior may be cultivated."}]','D','参考答案 D。末段说明文化、学校教育和养育影响合作，因此合作行为可以培养。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
