INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-1-6','cet4-2026-06-2',400,5,'This can create extraordinary results.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-1-7','cet4-2026-06-2',400,6,'People can communicate with each other using music as the common language.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-2-1','cet4-2026-06-2',401,0,'One common musical thread between cultures is known as the pentatonic scale.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-2-2','cet4-2026-06-2',401,1,'It is astonishing how many cultures share this tool in approaching music.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-2-3','cet4-2026-06-2',401,2,'The pentatonic scale consists of five notes; “penta-” meaning 5, and “tonic” meaning tone or note.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-2-4','cet4-2026-06-2',401,3,'This scale can be found in music everywhere including that of Native Americans, Africans, and Asians.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-2-5','cet4-2026-06-2',401,4,'It is also found in popular music, blues, jazz, and rock.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-2-6','cet4-2026-06-2',401,5,'Using this five-note scale, musicians from around the globe have a medium through which they can relate, communicate, perform, and ultimately understand each other.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-3-1','cet4-2026-06-2',402,0,'Music is tied to specific perceptual (感知的), mental, and emotional faculties, including language (all societies put words to their songs), motor control (people in all societies dance), sound analysis (all musical systems have a distinct pitch and quality), and aesthetics (美感) (their tunes and rhythms are balanced between repetitiveness and chaos).','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-1','cet4-2026-06-2',403,0,'There is no known society that existed without music.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-2','cet4-2026-06-2',403,1,'Although each culture has their own specific style and approach to music, you will find that the purposes behind music are very similar across the board.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-3','cet4-2026-06-2',403,2,'Music essentially serves to express or change emotions.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-4','cet4-2026-06-2',403,3,'It can cheer you up, sadden you, anger you or excite you.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-5','cet4-2026-06-2',403,4,'Music is often ceremonial: used in religion, ceremony, and celebration.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-6','cet4-2026-06-2',403,5,'Music can simply be recreational: entertaining, joyful and fun.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-7','cet4-2026-06-2',403,6,'Any way you have used music, it is almost certain that every other culture has used music in the very same way.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-8','cet4-2026-06-2',403,7,'And that is something that bonds all of us.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-5-sentence-4-9','cet4-2026-06-2',403,8,'We all share a deep love for music and it has the power to unite us.','cet4-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-2-section-6','cet4-2026-06-2',5,'translation','翻译 · 汉译英','Part IV · Translation · 30 minutes','["餐桌礼仪(dining etiquette)是中华传统文化的重要组成部分，蕴含着热情有礼的待客之道。为了招待客人，主人会根据客人的口味和喜好准备丰富精致的菜肴。就餐座位的安排非常讲究，主人坐在正对大门的位置，在主人身边就座的是最重要的客人。进餐时，主人会不时地为客人添酒加菜。这种独特的餐桌礼仪已延续了数千年，对促进和谐的人际交往起到了重要作用。"]','[]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
